PARTES = json.loads(r'''{"1": {"titulo": "Estructura base del proyecto", "commit": "feat: estructura base del proyecto con FastAPI y SQLAlchemy", "archivos": {".gitignore": "__pycache__/\n*.py[cod]\n.venv/\nvenv/\n.env\n*.db\n.pytest_cache/\n.idea/\n.vscode/\n", ".env.example": "APP_NAME=Finanzas App\nDEBUG=true\nDATABASE_URL=sqlite:///./finanzas.db\n", "requirements.txt": "fastapi==0.115.0\nuvicorn[standard]==0.30.6\nsqlalchemy==2.0.35\npydantic==2.9.2\npydantic-settings==2.5.2\npytest==8.3.3\nhttpx==0.27.2\n", "README.md": "# Finanzas App\n\nAplicación de finanzas personales para centralizar cuentas bancarias, registrar\ngastos e ingresos, y obtener reportes sobre los hábitos de gasto.\n\n## Stack\n\n- Python 3.11+\n- FastAPI\n- SQLAlchemy 2.0 + SQLite\n- Pytest\n\n## Instalación\n\n```bash\npython -m venv .venv\nsource .venv/bin/activate   # En Windows: .venv\\Scripts\\activate\npip install -r requirements.txt\ncp .env.example .env\n```\n\n## Ejecución\n\n```bash\nuvicorn app.main:app --reload\n```\n\nDocumentación interactiva: http://127.0.0.1:8000/docs\n\n## Pruebas\n\n```bash\npytest\n```\n\n## Estructura\n\n```\napp/\n  core/       configuración y base de datos\n  models/     modelos SQLAlchemy\n  schemas/    esquemas Pydantic\n  routers/    endpoints\n  services/   lógica de negocio\ntests/\n```\n", "app/__init__.py": "", "app/core/__init__.py": "", "app/core/config.py": "from pydantic_settings import BaseSettings, SettingsConfigDict\n\n\nclass Settings(BaseSettings):\n    \"\"\"Configuración de la aplicación, cargada desde variables de entorno o .env.\"\"\"\n\n    app_name: str = \"Finanzas App\"\n    debug: bool = True\n    database_url: str = \"sqlite:///./finanzas.db\"\n\n    model_config = SettingsConfigDict(env_file=\".env\", extra=\"ignore\")\n\n\nsettings = Settings()\n", "app/core/database.py": "from sqlalchemy import create_engine\nfrom sqlalchemy.orm import DeclarativeBase, sessionmaker\n\nfrom app.core.config import settings\n\n# check_same_thread solo aplica a SQLite\nconnect_args = (\n    {\"check_same_thread\": False} if settings.database_url.startswith(\"sqlite\") else {}\n)\n\nengine = create_engine(settings.database_url, connect_args=connect_args)\nSessionLocal = sessionmaker(bind=engine, autoflush=False, autocommit=False)\n\n\nclass Base(DeclarativeBase):\n    \"\"\"Clase base para todos los modelos.\"\"\"\n\n\ndef get_db():\n    \"\"\"Dependencia de FastAPI que entrega una sesión y la cierra al terminar.\"\"\"\n    db = SessionLocal()\n    try:\n        yield db\n    finally:\n        db.close()\n", "app/main.py": "from fastapi import FastAPI\n\nfrom app.core.config import settings\n\n\napp = FastAPI(title=settings.app_name, debug=settings.debug)\n\n\n@app.get(\"/health\", tags=[\"sistema\"])\ndef health():\n    \"\"\"Verifica que la API está en funcionamiento.\"\"\"\n    return {\"status\": \"ok\", \"app\": settings.app_name}\n", "app/models/__init__.py": "", "app/routers/__init__.py": "", "app/schemas/__init__.py": "", "app/services/__init__.py": "", "tests/test_health.py": "from fastapi.testclient import TestClient\n\nfrom app.main import app\n\nclient = TestClient(app)\n\n\ndef test_health():\n    response = client.get(\"/health\")\n    assert response.status_code == 200\n    assert response.json()[\"status\"] == \"ok\"\n"}}, "2": {"titulo": "Modelos de base de datos", "commit": "feat: modelos de base de datos (usuarios, cuentas, categorias, movimientos, presupuestos y notificaciones)", "archivos": {"app/main.py": "from contextlib import asynccontextmanager\n\nfrom fastapi import FastAPI\n\nfrom app import models  # noqa: F401\nfrom app.core.config import settings\nfrom app.core.database import Base, engine\n\n\n@asynccontextmanager\nasync def lifespan(app: FastAPI):\n    \"\"\"Crea las tablas de la base de datos al iniciar la aplicación.\"\"\"\n    Base.metadata.create_all(bind=engine)\n    yield\n\n\napp = FastAPI(title=settings.app_name, debug=settings.debug, lifespan=lifespan)\n\n\n@app.get(\"/health\", tags=[\"sistema\"])\ndef health():\n    \"\"\"Verifica que la API está en funcionamiento.\"\"\"\n    return {\"status\": \"ok\", \"app\": settings.app_name}\n", "pytest.ini": "[pytest]\ntestpaths = tests\npythonpath = .\nfilterwarnings =\n    ignore::DeprecationWarning\n    ignore::sqlalchemy.exc.SAWarning\n", "app/models/__init__.py": "from app.models.account import Account\nfrom app.models.budget import Budget\nfrom app.models.category import Category\nfrom app.models.enums import AccountType, NotificationKind, TransactionType\nfrom app.models.notification import Notification\nfrom app.models.transaction import Transaction\nfrom app.models.user import User\n\n__all__ = [\n    \"Account\",\n    \"AccountType\",\n    \"Budget\",\n    \"Category\",\n    \"Notification\",\n    \"NotificationKind\",\n    \"Transaction\",\n    \"TransactionType\",\n    \"User\",\n]\n", "app/models/enums.py": "import enum\n\n\nclass AccountType(str, enum.Enum):\n    checking = \"checking\"  # cuenta corriente\n    savings = \"savings\"  # cuenta de ahorros\n    credit_card = \"credit_card\"  # tarjeta de crédito\n    cash = \"cash\"  # efectivo\n    wallet = \"wallet\"  # billetera digital (Nequi, Daviplata, etc.)\n\n\nclass TransactionType(str, enum.Enum):\n    income = \"income\"\n    expense = \"expense\"\n\n\nclass NotificationKind(str, enum.Enum):\n    large_transaction = \"large_transaction\"\n    budget_warning = \"budget_warning\"\n    budget_exceeded = \"budget_exceeded\"\n", "app/models/user.py": "import datetime as dt\n\nfrom sqlalchemy import Date, DateTime, String, func\nfrom sqlalchemy.orm import Mapped, mapped_column\n\nfrom app.core.database import Base\n\n\nclass User(Base):\n    __tablename__ = \"users\"\n\n    id: Mapped[int] = mapped_column(primary_key=True)\n    email: Mapped[str] = mapped_column(String(255), unique=True, index=True)\n    full_name: Mapped[str] = mapped_column(String(120))\n    password_hash: Mapped[str] = mapped_column(String(255))\n    birth_date: Mapped[dt.date] = mapped_column(Date)\n    created_at: Mapped[dt.datetime] = mapped_column(\n        DateTime, server_default=func.now()\n    )\n", "app/models/account.py": "import datetime as dt\nfrom decimal import Decimal\n\nfrom sqlalchemy import Boolean, DateTime, Enum, ForeignKey, Numeric, String, func\nfrom sqlalchemy.orm import Mapped, mapped_column\n\nfrom app.core.database import Base\nfrom app.models.enums import AccountType\n\n\nclass Account(Base):\n    \"\"\"Cuenta financiera vinculada por el usuario.\n\n    Por seguridad solo se guardan los últimos 4 dígitos (last4); nunca el\n    número completo ni credenciales bancarias.\n    \"\"\"\n\n    __tablename__ = \"accounts\"\n\n    id: Mapped[int] = mapped_column(primary_key=True)\n    user_id: Mapped[int] = mapped_column(ForeignKey(\"users.id\"), index=True)\n    name: Mapped[str] = mapped_column(String(80))\n    institution: Mapped[str] = mapped_column(String(80), default=\"\")\n    account_type: Mapped[AccountType] = mapped_column(\n        Enum(AccountType, native_enum=False, length=20), default=AccountType.checking\n    )\n    last4: Mapped[str | None] = mapped_column(String(4), nullable=True)\n    currency: Mapped[str] = mapped_column(String(3), default=\"COP\")\n    initial_balance: Mapped[Decimal] = mapped_column(\n        Numeric(14, 2), default=Decimal(\"0\")\n    )\n    is_active: Mapped[bool] = mapped_column(Boolean, default=True)\n    created_at: Mapped[dt.datetime] = mapped_column(\n        DateTime, server_default=func.now()\n    )\n", "app/models/category.py": "from sqlalchemy import Enum, ForeignKey, String, UniqueConstraint\nfrom sqlalchemy.orm import Mapped, mapped_column\n\nfrom app.core.database import Base\nfrom app.models.enums import TransactionType\n\n\nclass Category(Base):\n    __tablename__ = \"categories\"\n    __table_args__ = (\n        UniqueConstraint(\"user_id\", \"name\", \"type\", name=\"uq_category_user_name_type\"),\n    )\n\n    id: Mapped[int] = mapped_column(primary_key=True)\n    user_id: Mapped[int] = mapped_column(ForeignKey(\"users.id\"), index=True)\n    name: Mapped[str] = mapped_column(String(60))\n    type: Mapped[TransactionType] = mapped_column(\n        Enum(TransactionType, native_enum=False, length=20)\n    )\n", "app/models/transaction.py": "import datetime as dt\nfrom decimal import Decimal\n\nfrom sqlalchemy import Date, DateTime, Enum, ForeignKey, Numeric, String, func\nfrom sqlalchemy.orm import Mapped, mapped_column\n\nfrom app.core.database import Base\nfrom app.models.enums import TransactionType\n\n\nclass Transaction(Base):\n    \"\"\"Movimiento de dinero (ingreso o gasto) asociado a una cuenta y categoría.\"\"\"\n\n    __tablename__ = \"transactions\"\n\n    id: Mapped[int] = mapped_column(primary_key=True)\n    user_id: Mapped[int] = mapped_column(ForeignKey(\"users.id\"), index=True)\n    account_id: Mapped[int] = mapped_column(ForeignKey(\"accounts.id\"), index=True)\n    category_id: Mapped[int] = mapped_column(ForeignKey(\"categories.id\"), index=True)\n    type: Mapped[TransactionType] = mapped_column(\n        Enum(TransactionType, native_enum=False, length=20)\n    )\n    amount: Mapped[Decimal] = mapped_column(Numeric(14, 2))\n    description: Mapped[str] = mapped_column(String(255), default=\"\")\n    date: Mapped[dt.date] = mapped_column(Date, index=True)\n    created_at: Mapped[dt.datetime] = mapped_column(\n        DateTime, server_default=func.now()\n    )\n", "app/models/budget.py": "from decimal import Decimal\n\nfrom sqlalchemy import ForeignKey, Numeric, UniqueConstraint\nfrom sqlalchemy.orm import Mapped, mapped_column\n\nfrom app.core.database import Base\n\n\nclass Budget(Base):\n    \"\"\"Límite mensual de gasto para una categoría.\"\"\"\n\n    __tablename__ = \"budgets\"\n    __table_args__ = (\n        UniqueConstraint(\"user_id\", \"category_id\", name=\"uq_budget_user_category\"),\n    )\n\n    id: Mapped[int] = mapped_column(primary_key=True)\n    user_id: Mapped[int] = mapped_column(ForeignKey(\"users.id\"), index=True)\n    category_id: Mapped[int] = mapped_column(ForeignKey(\"categories.id\"))\n    monthly_limit: Mapped[Decimal] = mapped_column(Numeric(14, 2))\n    # Fracción del límite a partir de la cual se envía una alerta (0.80 = 80%)\n    alert_threshold: Mapped[Decimal] = mapped_column(\n        Numeric(3, 2), default=Decimal(\"0.80\")\n    )\n", "app/models/notification.py": "import datetime as dt\n\nfrom sqlalchemy import Boolean, DateTime, Enum, ForeignKey, String, func\nfrom sqlalchemy.orm import Mapped, mapped_column\n\nfrom app.core.database import Base\nfrom app.models.enums import NotificationKind\n\n\nclass Notification(Base):\n    __tablename__ = \"notifications\"\n\n    id: Mapped[int] = mapped_column(primary_key=True)\n    user_id: Mapped[int] = mapped_column(ForeignKey(\"users.id\"), index=True)\n    kind: Mapped[NotificationKind] = mapped_column(\n        Enum(NotificationKind, native_enum=False, length=30)\n    )\n    message: Mapped[str] = mapped_column(String(500))\n    is_read: Mapped[bool] = mapped_column(Boolean, default=False)\n    created_at: Mapped[dt.datetime] = mapped_column(\n        DateTime, server_default=func.now()\n    )\n", "tests/conftest.py": "import pytest\nfrom fastapi.testclient import TestClient\nfrom sqlalchemy import create_engine\nfrom sqlalchemy.orm import sessionmaker\nfrom sqlalchemy.pool import StaticPool\n\nfrom app import models  # noqa: F401\nfrom app.core.database import Base, get_db\nfrom app.main import app\n\n\n@pytest.fixture()\ndef db_session():\n    \"\"\"Base de datos SQLite en memoria, nueva para cada prueba.\"\"\"\n    engine = create_engine(\n        \"sqlite://\",\n        connect_args={\"check_same_thread\": False},\n        poolclass=StaticPool,\n    )\n    Base.metadata.create_all(bind=engine)\n    session = sessionmaker(bind=engine, autoflush=False, autocommit=False)()\n    try:\n        yield session\n    finally:\n        session.close()\n        engine.dispose()\n\n\n@pytest.fixture()\ndef client(db_session):\n    def override_get_db():\n        yield db_session\n\n    app.dependency_overrides[get_db] = override_get_db\n    yield TestClient(app)\n    app.dependency_overrides.clear()\n", "tests/test_models.py": "import datetime as dt\nfrom decimal import Decimal\n\nfrom app.models import (\n    Account,\n    Category,\n    Transaction,\n    TransactionType,\n    User,\n)\n\n\ndef test_crear_y_leer_movimiento(db_session):\n    user = User(\n        email=\"ana@example.com\",\n        full_name=\"Ana Pérez\",\n        password_hash=\"x\",\n        birth_date=dt.date(1995, 5, 10),\n    )\n    db_session.add(user)\n    db_session.flush()\n\n    account = Account(user_id=user.id, name=\"Bancolombia\", initial_balance=Decimal(\"1000\"))\n    category = Category(user_id=user.id, name=\"Alimentación\", type=TransactionType.expense)\n    db_session.add_all([account, category])\n    db_session.flush()\n\n    db_session.add(\n        Transaction(\n            user_id=user.id,\n            account_id=account.id,\n            category_id=category.id,\n            type=TransactionType.expense,\n            amount=Decimal(\"1500.50\"),\n            description=\"Mercado\",\n            date=dt.date(2026, 10, 5),\n        )\n    )\n    db_session.commit()\n\n    saved = db_session.query(Transaction).one()\n    assert saved.amount == Decimal(\"1500.50\")\n    assert saved.type == TransactionType.expense\n    assert saved.date == dt.date(2026, 10, 5)\n"}}, "3": {"titulo": "Registro e inicio de sesión", "commit": "feat: registro e inicio de sesion con JWT y categorias por defecto", "archivos": {"requirements.txt": "fastapi==0.115.0\nuvicorn[standard]==0.30.6\nsqlalchemy==2.0.35\npydantic==2.9.2\npydantic-settings==2.5.2\npyjwt==2.9.0\npytest==8.3.3\nhttpx==0.27.2\n", ".env.example": "APP_NAME=Finanzas App\nDEBUG=true\nDATABASE_URL=sqlite:///./finanzas.db\nSECRET_KEY=cambia-esta-clave-en-produccion\nACCESS_TOKEN_EXPIRE_MINUTES=60\n", "app/core/config.py": "from pydantic_settings import BaseSettings, SettingsConfigDict\n\n\nclass Settings(BaseSettings):\n    \"\"\"Configuración de la aplicación, cargada desde variables de entorno o .env.\"\"\"\n\n    app_name: str = \"Finanzas App\"\n    debug: bool = True\n    database_url: str = \"sqlite:///./finanzas.db\"\n    secret_key: str = \"cambia-esta-clave-en-produccion\"\n    algorithm: str = \"HS256\"\n    access_token_expire_minutes: int = 60\n\n    model_config = SettingsConfigDict(env_file=\".env\", extra=\"ignore\")\n\n\nsettings = Settings()\n", "app/core/security.py": "import base64\nimport hashlib\nimport hmac\nimport os\nfrom datetime import datetime, timedelta, timezone\n\nimport jwt\n\nfrom app.core.config import settings\n\n_ITERATIONS = 200_000\n\n\ndef hash_password(password: str) -> str:\n    \"\"\"Genera un hash PBKDF2-SHA256 con sal aleatoria.\"\"\"\n    salt = os.urandom(16)\n    digest = hashlib.pbkdf2_hmac(\"sha256\", password.encode(), salt, _ITERATIONS)\n    return f\"{base64.b64encode(salt).decode()}${base64.b64encode(digest).decode()}\"\n\n\ndef verify_password(password: str, stored_hash: str) -> bool:\n    try:\n        salt_b64, digest_b64 = stored_hash.split(\"$\")\n        salt = base64.b64decode(salt_b64)\n        expected = base64.b64decode(digest_b64)\n    except ValueError:\n        return False\n    digest = hashlib.pbkdf2_hmac(\"sha256\", password.encode(), salt, _ITERATIONS)\n    return hmac.compare_digest(digest, expected)\n\n\ndef create_access_token(user_id: int) -> str:\n    expire = datetime.now(timezone.utc) + timedelta(\n        minutes=settings.access_token_expire_minutes\n    )\n    payload = {\"sub\": str(user_id), \"exp\": expire}\n    return jwt.encode(payload, settings.secret_key, algorithm=settings.algorithm)\n\n\ndef decode_access_token(token: str) -> int | None:\n    \"\"\"Devuelve el id del usuario del token, o None si es inválido o expiró.\"\"\"\n    try:\n        payload = jwt.decode(token, settings.secret_key, algorithms=[settings.algorithm])\n        return int(payload[\"sub\"])\n    except (jwt.PyJWTError, KeyError, ValueError):\n        return None\n", "app/core/deps.py": "from typing import Annotated\n\nfrom fastapi import Depends, HTTPException, status\nfrom fastapi.security import HTTPAuthorizationCredentials, HTTPBearer\nfrom sqlalchemy.orm import Session\n\nfrom app.core.database import get_db\nfrom app.core.security import decode_access_token\nfrom app.models import User\n\nbearer_scheme = HTTPBearer(auto_error=False)\n\nDbSession = Annotated[Session, Depends(get_db)]\n\n\ndef get_current_user(\n    credentials: Annotated[HTTPAuthorizationCredentials | None, Depends(bearer_scheme)],\n    db: DbSession,\n) -> User:\n    \"\"\"Obtiene el usuario autenticado a partir del token Bearer.\"\"\"\n    user_id = decode_access_token(credentials.credentials) if credentials else None\n    user = db.get(User, user_id) if user_id else None\n    if user is None:\n        raise HTTPException(\n            status.HTTP_401_UNAUTHORIZED,\n            \"Token inválido o expirado\",\n            headers={\"WWW-Authenticate\": \"Bearer\"},\n        )\n    return user\n\n\nCurrentUser = Annotated[User, Depends(get_current_user)]\n", "app/schemas/user.py": "import datetime as dt\n\nfrom pydantic import BaseModel, ConfigDict, Field, field_validator\n\nEMAIL_PATTERN = r\"^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$\"\n\n\nclass UserCreate(BaseModel):\n    email: str = Field(pattern=EMAIL_PATTERN, max_length=255)\n    full_name: str = Field(min_length=2, max_length=120)\n    password: str = Field(min_length=8, max_length=128)\n    birth_date: dt.date\n\n    @field_validator(\"email\")\n    @classmethod\n    def normalize_email(cls, value: str) -> str:\n        return value.lower()\n\n    @field_validator(\"birth_date\")\n    @classmethod\n    def must_be_adult(cls, value: dt.date) -> dt.date:\n        today = dt.date.today()\n        age = today.year - value.year - ((today.month, today.day) < (value.month, value.day))\n        if age < 18:\n            raise ValueError(\"Debes ser mayor de 18 años para usar la aplicación\")\n        return value\n\n\nclass UserLogin(BaseModel):\n    email: str\n    password: str\n\n\nclass UserOut(BaseModel):\n    model_config = ConfigDict(from_attributes=True)\n\n    id: int\n    email: str\n    full_name: str\n    birth_date: dt.date\n    created_at: dt.datetime\n\n\nclass Token(BaseModel):\n    access_token: str\n    token_type: str = \"bearer\"\n", "app/services/categories.py": "from fastapi import HTTPException, status\nfrom sqlalchemy import select\nfrom sqlalchemy.orm import Session\n\nfrom app.models import Category, TransactionType\n\nDEFAULT_CATEGORIES = [\n    (\"Alimentación\", TransactionType.expense),\n    (\"Transporte\", TransactionType.expense),\n    (\"Vivienda\", TransactionType.expense),\n    (\"Servicios\", TransactionType.expense),\n    (\"Salud\", TransactionType.expense),\n    (\"Educación\", TransactionType.expense),\n    (\"Entretenimiento\", TransactionType.expense),\n    (\"Ropa\", TransactionType.expense),\n    (\"Otros gastos\", TransactionType.expense),\n    (\"Salario\", TransactionType.income),\n    (\"Ventas\", TransactionType.income),\n    (\"Otros ingresos\", TransactionType.income),\n]\n\n\ndef create_default_categories(db: Session, user_id: int) -> None:\n    \"\"\"Crea las categorías iniciales para un usuario nuevo.\"\"\"\n    db.add_all(\n        Category(user_id=user_id, name=name, type=tx_type)\n        for name, tx_type in DEFAULT_CATEGORIES\n    )\n\n\ndef get_user_category(db: Session, user_id: int, category_id: int) -> Category:\n    category = db.scalar(\n        select(Category).where(Category.id == category_id, Category.user_id == user_id)\n    )\n    if category is None:\n        raise HTTPException(status.HTTP_404_NOT_FOUND, \"Categoría no encontrada\")\n    return category\n", "app/routers/auth.py": "from fastapi import APIRouter, HTTPException, status\nfrom sqlalchemy import select\n\nfrom app.core.deps import CurrentUser, DbSession\nfrom app.core.security import create_access_token, hash_password, verify_password\nfrom app.models import User\nfrom app.schemas.user import Token, UserCreate, UserLogin, UserOut\nfrom app.services.categories import create_default_categories\n\nrouter = APIRouter(prefix=\"/auth\", tags=[\"autenticación\"])\n\n\n@router.post(\"/register\", response_model=UserOut, status_code=status.HTTP_201_CREATED)\ndef register(data: UserCreate, db: DbSession):\n    \"\"\"Registra un usuario adulto (18+) y le crea categorías por defecto.\"\"\"\n    if db.scalar(select(User).where(User.email == data.email)):\n        raise HTTPException(\n            status.HTTP_409_CONFLICT, \"Ya existe un usuario con ese correo\"\n        )\n    user = User(\n        email=data.email,\n        full_name=data.full_name,\n        password_hash=hash_password(data.password),\n        birth_date=data.birth_date,\n    )\n    db.add(user)\n    db.flush()\n    create_default_categories(db, user.id)\n    db.commit()\n    db.refresh(user)\n    return user\n\n\n@router.post(\"/login\", response_model=Token)\ndef login(data: UserLogin, db: DbSession):\n    user = db.scalar(select(User).where(User.email == data.email.lower()))\n    if user is None or not verify_password(data.password, user.password_hash):\n        raise HTTPException(\n            status.HTTP_401_UNAUTHORIZED, \"Correo o contraseña incorrectos\"\n        )\n    return Token(access_token=create_access_token(user.id))\n\n\n@router.get(\"/me\", response_model=UserOut)\ndef me(user: CurrentUser):\n    return user\n", "app/main.py": "from contextlib import asynccontextmanager\n\nfrom fastapi import FastAPI\n\nfrom app import models  # noqa: F401\nfrom app.core.config import settings\nfrom app.core.database import Base, engine\nfrom app.routers import auth\n\n\n@asynccontextmanager\nasync def lifespan(app: FastAPI):\n    \"\"\"Crea las tablas de la base de datos al iniciar la aplicación.\"\"\"\n    Base.metadata.create_all(bind=engine)\n    yield\n\n\napp = FastAPI(title=settings.app_name, debug=settings.debug, lifespan=lifespan)\n\napp.include_router(auth.router)\n\n\n@app.get(\"/health\", tags=[\"sistema\"])\ndef health():\n    \"\"\"Verifica que la API está en funcionamiento.\"\"\"\n    return {\"status\": \"ok\", \"app\": settings.app_name}\n", "tests/conftest.py": "import pytest\nfrom fastapi.testclient import TestClient\nfrom sqlalchemy import create_engine\nfrom sqlalchemy.orm import sessionmaker\nfrom sqlalchemy.pool import StaticPool\n\nfrom app import models  # noqa: F401\nfrom app.core.database import Base, get_db\nfrom app.main import app\n\n\n@pytest.fixture()\ndef db_session():\n    \"\"\"Base de datos SQLite en memoria, nueva para cada prueba.\"\"\"\n    engine = create_engine(\n        \"sqlite://\",\n        connect_args={\"check_same_thread\": False},\n        poolclass=StaticPool,\n    )\n    Base.metadata.create_all(bind=engine)\n    session = sessionmaker(bind=engine, autoflush=False, autocommit=False)()\n    try:\n        yield session\n    finally:\n        session.close()\n        engine.dispose()\n\n\n@pytest.fixture()\ndef client(db_session):\n    def override_get_db():\n        yield db_session\n\n    app.dependency_overrides[get_db] = override_get_db\n    yield TestClient(app)\n    app.dependency_overrides.clear()\n\n\n@pytest.fixture()\ndef make_headers(client):\n    \"\"\"Entrega una función que registra un usuario y devuelve su encabezado de autenticación.\"\"\"\n\n    def _make(email: str = \"ana@example.com\") -> dict[str, str]:\n        client.post(\n            \"/auth/register\",\n            json={\n                \"email\": email,\n                \"full_name\": \"Ana Pérez\",\n                \"password\": \"Contrasena123\",\n                \"birth_date\": \"1995-05-10\",\n            },\n        )\n        response = client.post(\n            \"/auth/login\", json={\"email\": email, \"password\": \"Contrasena123\"}\n        )\n        return {\"Authorization\": f\"Bearer {response.json()['access_token']}\"}\n\n    return _make\n\n\n@pytest.fixture()\ndef auth_headers(make_headers):\n    return make_headers()\n", "tests/test_auth.py": "import datetime as dt\n\nfrom sqlalchemy import func, select\n\nfrom app.models import Category\n\nVALID_USER = {\n    \"email\": \"ana@example.com\",\n    \"full_name\": \"Ana Pérez\",\n    \"password\": \"Contrasena123\",\n    \"birth_date\": \"1995-05-10\",\n}\n\n\ndef test_registro_exitoso(client, db_session):\n    response = client.post(\"/auth/register\", json=VALID_USER)\n    assert response.status_code == 201\n    body = response.json()\n    assert body[\"email\"] == \"ana@example.com\"\n    assert \"password\" not in body and \"password_hash\" not in body\n\n    # Se crean las categorías por defecto\n    total = db_session.scalar(select(func.count()).select_from(Category))\n    assert total == 12\n\n\ndef test_correo_se_guarda_en_minusculas(client):\n    response = client.post(\"/auth/register\", json={**VALID_USER, \"email\": \"ANA@Example.com\"})\n    assert response.json()[\"email\"] == \"ana@example.com\"\n\n\ndef test_correo_duplicado(client):\n    client.post(\"/auth/register\", json=VALID_USER)\n    response = client.post(\"/auth/register\", json=VALID_USER)\n    assert response.status_code == 409\n\n\ndef test_menor_de_edad_no_puede_registrarse(client):\n    hace_diez_anos = (dt.date.today() - dt.timedelta(days=365 * 10)).isoformat()\n    response = client.post(\"/auth/register\", json={**VALID_USER, \"birth_date\": hace_diez_anos})\n    assert response.status_code == 422\n\n\ndef test_contrasena_corta(client):\n    response = client.post(\"/auth/register\", json={**VALID_USER, \"password\": \"123\"})\n    assert response.status_code == 422\n\n\ndef test_login_correcto_e_incorrecto(client):\n    client.post(\"/auth/register\", json=VALID_USER)\n\n    ok = client.post(\"/auth/login\", json={\"email\": \"ana@example.com\", \"password\": \"Contrasena123\"})\n    assert ok.status_code == 200\n    assert ok.json()[\"token_type\"] == \"bearer\"\n\n    mal = client.post(\"/auth/login\", json={\"email\": \"ana@example.com\", \"password\": \"otra-clave\"})\n    assert mal.status_code == 401\n\n\ndef test_me_requiere_token(client, auth_headers):\n    assert client.get(\"/auth/me\").status_code == 401\n    assert client.get(\"/auth/me\", headers={\"Authorization\": \"Bearer falso\"}).status_code == 401\n\n    response = client.get(\"/auth/me\", headers=auth_headers)\n    assert response.status_code == 200\n    assert response.json()[\"email\"] == \"ana@example.com\"\n"}}, "4": {"titulo": "Cuentas vinculadas", "commit": "feat: vinculacion y gestion de cuentas con calculo de saldo", "archivos": {"app/core/money.py": "from decimal import ROUND_HALF_UP, Decimal\n\nCENTS = Decimal(\"0.01\")\n\n\ndef to_money(value) -> Decimal:\n    \"\"\"Convierte cualquier valor numérico a Decimal con 2 decimales.\"\"\"\n    return Decimal(str(value or 0)).quantize(CENTS, rounding=ROUND_HALF_UP)\n\n\ndef format_money(value) -> str:\n    \"\"\"Formatea un valor en pesos, por ejemplo $1.500.000.\"\"\"\n    amount = to_money(value)\n    sign = \"-\" if amount < 0 else \"\"\n    return f\"{sign}${abs(amount):,.0f}\".replace(\",\", \".\")\n", "app/schemas/account.py": "import datetime as dt\nfrom decimal import Decimal\n\nfrom pydantic import BaseModel, ConfigDict, Field\n\nfrom app.models.enums import AccountType\n\n\nclass AccountCreate(BaseModel):\n    name: str = Field(min_length=1, max_length=80)\n    institution: str = Field(default=\"\", max_length=80)\n    account_type: AccountType = AccountType.checking\n    last4: str | None = Field(default=None, pattern=r\"^\\d{4}$\")\n    currency: str = Field(default=\"COP\", min_length=3, max_length=3)\n    initial_balance: Decimal = Field(default=Decimal(\"0\"), max_digits=14, decimal_places=2)\n\n\nclass AccountUpdate(BaseModel):\n    name: str | None = Field(default=None, min_length=1, max_length=80)\n    institution: str | None = Field(default=None, max_length=80)\n    last4: str | None = Field(default=None, pattern=r\"^\\d{4}$\")\n    is_active: bool | None = None\n\n\nclass AccountOut(BaseModel):\n    model_config = ConfigDict(from_attributes=True)\n\n    id: int\n    name: str\n    institution: str\n    account_type: AccountType\n    last4: str | None\n    currency: str\n    initial_balance: Decimal\n    is_active: bool\n    created_at: dt.datetime\n    balance: Decimal = Decimal(\"0\")\n", "app/services/accounts.py": "from decimal import Decimal\n\nfrom fastapi import HTTPException, status\nfrom sqlalchemy import func, select\nfrom sqlalchemy.orm import Session\n\nfrom app.core.money import to_money\nfrom app.models import Account, Transaction, TransactionType\n\n\ndef get_user_account(db: Session, user_id: int, account_id: int) -> Account:\n    account = db.scalar(\n        select(Account).where(Account.id == account_id, Account.user_id == user_id)\n    )\n    if account is None:\n        raise HTTPException(status.HTTP_404_NOT_FOUND, \"Cuenta no encontrada\")\n    return account\n\n\ndef compute_balances(db: Session, user_id: int) -> dict[int, Decimal]:\n    \"\"\"Saldo de cada cuenta del usuario: saldo inicial + ingresos - gastos.\"\"\"\n    accounts = db.scalars(select(Account).where(Account.user_id == user_id)).all()\n    balances = {a.id: to_money(a.initial_balance) for a in accounts}\n\n    rows = db.execute(\n        select(Transaction.account_id, Transaction.type, func.sum(Transaction.amount))\n        .where(Transaction.user_id == user_id)\n        .group_by(Transaction.account_id, Transaction.type)\n    ).all()\n    for account_id, tx_type, total in rows:\n        sign = 1 if tx_type == TransactionType.income else -1\n        balances[account_id] = balances.get(account_id, Decimal(\"0.00\")) + sign * to_money(total)\n    return balances\n\n\ndef total_balance(db: Session, user_id: int) -> Decimal:\n    \"\"\"Saldo total sumando solo las cuentas activas.\"\"\"\n    balances = compute_balances(db, user_id)\n    active_ids = db.scalars(\n        select(Account.id).where(Account.user_id == user_id, Account.is_active.is_(True))\n    ).all()\n    return sum((balances[i] for i in active_ids), Decimal(\"0.00\"))\n", "app/routers/accounts.py": "from fastapi import APIRouter, HTTPException, Response, status\nfrom sqlalchemy import func, select\n\nfrom app.core.deps import CurrentUser, DbSession\nfrom app.models import Account, Transaction\nfrom app.schemas.account import AccountCreate, AccountOut, AccountUpdate\nfrom app.services.accounts import compute_balances, get_user_account\n\nrouter = APIRouter(prefix=\"/accounts\", tags=[\"cuentas\"])\n\n\ndef _with_balance(db, user_id: int, account: Account) -> AccountOut:\n    balance = compute_balances(db, user_id)[account.id]\n    return AccountOut.model_validate(account).model_copy(update={\"balance\": balance})\n\n\n@router.post(\"\", response_model=AccountOut, status_code=status.HTTP_201_CREATED)\ndef link_account(data: AccountCreate, user: CurrentUser, db: DbSession):\n    \"\"\"Vincula una cuenta. Solo se guardan los últimos 4 dígitos, nunca claves.\"\"\"\n    account = Account(user_id=user.id, **data.model_dump())\n    db.add(account)\n    db.commit()\n    db.refresh(account)\n    return _with_balance(db, user.id, account)\n\n\n@router.get(\"\", response_model=list[AccountOut])\ndef list_accounts(user: CurrentUser, db: DbSession, include_inactive: bool = False):\n    query = select(Account).where(Account.user_id == user.id).order_by(Account.id)\n    if not include_inactive:\n        query = query.where(Account.is_active.is_(True))\n    balances = compute_balances(db, user.id)\n    return [\n        AccountOut.model_validate(a).model_copy(update={\"balance\": balances[a.id]})\n        for a in db.scalars(query)\n    ]\n\n\n@router.get(\"/{account_id}\", response_model=AccountOut)\ndef get_account(account_id: int, user: CurrentUser, db: DbSession):\n    return _with_balance(db, user.id, get_user_account(db, user.id, account_id))\n\n\n@router.patch(\"/{account_id}\", response_model=AccountOut)\ndef update_account(account_id: int, data: AccountUpdate, user: CurrentUser, db: DbSession):\n    account = get_user_account(db, user.id, account_id)\n    for field, value in data.model_dump(exclude_unset=True).items():\n        setattr(account, field, value)\n    db.commit()\n    db.refresh(account)\n    return _with_balance(db, user.id, account)\n\n\n@router.delete(\"/{account_id}\", status_code=status.HTTP_204_NO_CONTENT)\ndef delete_account(account_id: int, user: CurrentUser, db: DbSession):\n    account = get_user_account(db, user.id, account_id)\n    movements = db.scalar(\n        select(func.count()).select_from(Transaction).where(Transaction.account_id == account.id)\n    )\n    if movements:\n        raise HTTPException(\n            status.HTTP_409_CONFLICT,\n            \"La cuenta tiene movimientos; desactívala en lugar de eliminarla\",\n        )\n    db.delete(account)\n    db.commit()\n    return Response(status_code=status.HTTP_204_NO_CONTENT)\n", "app/main.py": "from contextlib import asynccontextmanager\n\nfrom fastapi import FastAPI\n\nfrom app import models  # noqa: F401\nfrom app.core.config import settings\nfrom app.core.database import Base, engine\nfrom app.routers import auth\nfrom app.routers import accounts\n\n\n@asynccontextmanager\nasync def lifespan(app: FastAPI):\n    \"\"\"Crea las tablas de la base de datos al iniciar la aplicación.\"\"\"\n    Base.metadata.create_all(bind=engine)\n    yield\n\n\napp = FastAPI(title=settings.app_name, debug=settings.debug, lifespan=lifespan)\n\napp.include_router(auth.router)\napp.include_router(accounts.router)\n\n\n@app.get(\"/health\", tags=[\"sistema\"])\ndef health():\n    \"\"\"Verifica que la API está en funcionamiento.\"\"\"\n    return {\"status\": \"ok\", \"app\": settings.app_name}\n", "tests/conftest.py": "import pytest\nfrom fastapi.testclient import TestClient\nfrom sqlalchemy import create_engine\nfrom sqlalchemy.orm import sessionmaker\nfrom sqlalchemy.pool import StaticPool\n\nfrom app import models  # noqa: F401\nfrom app.core.database import Base, get_db\nfrom app.main import app\n\n\n@pytest.fixture()\ndef db_session():\n    \"\"\"Base de datos SQLite en memoria, nueva para cada prueba.\"\"\"\n    engine = create_engine(\n        \"sqlite://\",\n        connect_args={\"check_same_thread\": False},\n        poolclass=StaticPool,\n    )\n    Base.metadata.create_all(bind=engine)\n    session = sessionmaker(bind=engine, autoflush=False, autocommit=False)()\n    try:\n        yield session\n    finally:\n        session.close()\n        engine.dispose()\n\n\n@pytest.fixture()\ndef client(db_session):\n    def override_get_db():\n        yield db_session\n\n    app.dependency_overrides[get_db] = override_get_db\n    yield TestClient(app)\n    app.dependency_overrides.clear()\n\n\n@pytest.fixture()\ndef make_headers(client):\n    \"\"\"Entrega una función que registra un usuario y devuelve su encabezado de autenticación.\"\"\"\n\n    def _make(email: str = \"ana@example.com\") -> dict[str, str]:\n        client.post(\n            \"/auth/register\",\n            json={\n                \"email\": email,\n                \"full_name\": \"Ana Pérez\",\n                \"password\": \"Contrasena123\",\n                \"birth_date\": \"1995-05-10\",\n            },\n        )\n        response = client.post(\n            \"/auth/login\", json={\"email\": email, \"password\": \"Contrasena123\"}\n        )\n        return {\"Authorization\": f\"Bearer {response.json()['access_token']}\"}\n\n    return _make\n\n\n@pytest.fixture()\ndef auth_headers(make_headers):\n    return make_headers()\n\n\n@pytest.fixture()\ndef account_id(client, auth_headers):\n    \"\"\"Crea una cuenta con saldo inicial de 1.000.000 y devuelve su id.\"\"\"\n    response = client.post(\n        \"/accounts\",\n        json={\n            \"name\": \"Bancolombia\",\n            \"institution\": \"Bancolombia\",\n            \"account_type\": \"checking\",\n            \"last4\": \"1234\",\n            \"initial_balance\": \"1000000\",\n        },\n        headers=auth_headers,\n    )\n    return response.json()[\"id\"]\n", "tests/test_accounts.py": "from decimal import Decimal\n\n\ndef test_vincular_cuenta_con_saldo(client, auth_headers):\n    response = client.post(\n        \"/accounts\",\n        json={\"name\": \"Nequi\", \"account_type\": \"wallet\", \"initial_balance\": \"250000.50\"},\n        headers=auth_headers,\n    )\n    assert response.status_code == 201\n    body = response.json()\n    assert body[\"name\"] == \"Nequi\"\n    assert Decimal(body[\"balance\"]) == Decimal(\"250000.50\")\n\n\ndef test_last4_debe_tener_cuatro_digitos(client, auth_headers):\n    response = client.post(\n        \"/accounts\",\n        json={\"name\": \"Tarjeta\", \"last4\": \"123456789\"},\n        headers=auth_headers,\n    )\n    assert response.status_code == 422\n\n\ndef test_listar_y_obtener_cuentas(client, auth_headers, account_id):\n    lista = client.get(\"/accounts\", headers=auth_headers).json()\n    assert [a[\"id\"] for a in lista] == [account_id]\n\n    una = client.get(f\"/accounts/{account_id}\", headers=auth_headers)\n    assert una.status_code == 200\n    assert Decimal(una.json()[\"balance\"]) == Decimal(\"1000000\")\n\n\ndef test_desactivar_cuenta_la_oculta_del_listado(client, auth_headers, account_id):\n    response = client.patch(\n        f\"/accounts/{account_id}\", json={\"is_active\": False}, headers=auth_headers\n    )\n    assert response.status_code == 200\n    assert client.get(\"/accounts\", headers=auth_headers).json() == []\n    todas = client.get(\"/accounts?include_inactive=true\", headers=auth_headers).json()\n    assert len(todas) == 1\n\n\ndef test_eliminar_cuenta_sin_movimientos(client, auth_headers, account_id):\n    assert client.delete(f\"/accounts/{account_id}\", headers=auth_headers).status_code == 204\n    assert client.get(f\"/accounts/{account_id}\", headers=auth_headers).status_code == 404\n\n\ndef test_un_usuario_no_ve_cuentas_de_otro(client, make_headers, account_id):\n    otro = make_headers(\"luis@example.com\")\n    assert client.get(f\"/accounts/{account_id}\", headers=otro).status_code == 404\n    assert client.get(\"/accounts\", headers=otro).json() == []\n\n\ndef test_cuentas_requieren_autenticacion(client):\n    assert client.get(\"/accounts\").status_code == 401\n"}}, "5": {"titulo": "Categorías y movimientos", "commit": "feat: categorias y registro de movimientos con filtros e historial", "archivos": {"app/schemas/category.py": "from pydantic import BaseModel, ConfigDict, Field\n\nfrom app.models.enums import TransactionType\n\n\nclass CategoryCreate(BaseModel):\n    name: str = Field(min_length=1, max_length=60)\n    type: TransactionType\n\n\nclass CategoryOut(BaseModel):\n    model_config = ConfigDict(from_attributes=True)\n\n    id: int\n    name: str\n    type: TransactionType\n", "app/schemas/transaction.py": "import datetime as dt\nfrom decimal import Decimal\n\nfrom pydantic import BaseModel, ConfigDict, Field\n\nfrom app.models.enums import TransactionType\n\n\nclass TransactionCreate(BaseModel):\n    account_id: int\n    category_id: int\n    type: TransactionType\n    amount: Decimal = Field(gt=0, max_digits=14, decimal_places=2)\n    description: str = Field(default=\"\", max_length=255)\n    date: dt.date = Field(default_factory=dt.date.today)\n\n\nclass TransactionUpdate(BaseModel):\n    account_id: int | None = None\n    category_id: int | None = None\n    type: TransactionType | None = None\n    amount: Decimal | None = Field(default=None, gt=0, max_digits=14, decimal_places=2)\n    description: str | None = Field(default=None, max_length=255)\n    date: dt.date | None = None\n\n\nclass TransactionOut(BaseModel):\n    model_config = ConfigDict(from_attributes=True)\n\n    id: int\n    account_id: int\n    category_id: int\n    type: TransactionType\n    amount: Decimal\n    description: str\n    date: dt.date\n    created_at: dt.datetime\n\n\nclass TransactionPage(BaseModel):\n    items: list[TransactionOut]\n    total: int\n    limit: int\n    offset: int\n", "app/services/transactions.py": "import datetime as dt\nfrom decimal import Decimal\n\nfrom fastapi import HTTPException, status\nfrom sqlalchemy import func, select\nfrom sqlalchemy.orm import Session\n\nfrom app.models import Transaction, TransactionType, User\nfrom app.schemas.transaction import TransactionCreate, TransactionUpdate\nfrom app.services.accounts import get_user_account\nfrom app.services.categories import get_user_category\n\n\ndef _validate_refs(\n    db: Session,\n    user_id: int,\n    account_id: int,\n    category_id: int,\n    tx_type: TransactionType,\n    check_active: bool = True,\n) -> None:\n    account = get_user_account(db, user_id, account_id)\n    if check_active and not account.is_active:\n        raise HTTPException(status.HTTP_400_BAD_REQUEST, \"La cuenta está inactiva\")\n    category = get_user_category(db, user_id, category_id)\n    if category.type != tx_type:\n        raise HTTPException(\n            status.HTTP_400_BAD_REQUEST,\n            \"La categoría no corresponde al tipo de movimiento\",\n        )\n\n\ndef get_user_transaction(db: Session, user_id: int, tx_id: int) -> Transaction:\n    tx = db.scalar(\n        select(Transaction).where(Transaction.id == tx_id, Transaction.user_id == user_id)\n    )\n    if tx is None:\n        raise HTTPException(status.HTTP_404_NOT_FOUND, \"Movimiento no encontrado\")\n    return tx\n\n\ndef create_transaction(db: Session, user: User, data: TransactionCreate) -> Transaction:\n    _validate_refs(db, user.id, data.account_id, data.category_id, data.type)\n    tx = Transaction(user_id=user.id, **data.model_dump())\n    db.add(tx)\n    db.flush()\n    db.commit()\n    db.refresh(tx)\n    return tx\n\n\ndef update_transaction(\n    db: Session, user: User, tx_id: int, data: TransactionUpdate\n) -> Transaction:\n    tx = get_user_transaction(db, user.id, tx_id)\n    changes = data.model_dump(exclude_unset=True, exclude_none=True)\n    merged = {\n        \"account_id\": tx.account_id,\n        \"category_id\": tx.category_id,\n        \"type\": tx.type,\n        **{k: v for k, v in changes.items() if k in (\"account_id\", \"category_id\", \"type\")},\n    }\n    _validate_refs(\n        db,\n        user.id,\n        merged[\"account_id\"],\n        merged[\"category_id\"],\n        merged[\"type\"],\n        check_active=\"account_id\" in changes,\n    )\n    for field, value in changes.items():\n        setattr(tx, field, value)\n    db.commit()\n    db.refresh(tx)\n    return tx\n\n\ndef delete_transaction(db: Session, user: User, tx_id: int) -> None:\n    tx = get_user_transaction(db, user.id, tx_id)\n    db.delete(tx)\n    db.commit()\n\n\ndef search_transactions(\n    db: Session,\n    user_id: int,\n    *,\n    account_id: int | None = None,\n    category_id: int | None = None,\n    tx_type: TransactionType | None = None,\n    date_from: dt.date | None = None,\n    date_to: dt.date | None = None,\n    min_amount: Decimal | None = None,\n    max_amount: Decimal | None = None,\n    search: str | None = None,\n    limit: int = 50,\n    offset: int = 0,\n) -> tuple[list[Transaction], int]:\n    \"\"\"Historial de movimientos con filtros. Devuelve (movimientos, total).\"\"\"\n    query = select(Transaction).where(Transaction.user_id == user_id)\n    if account_id is not None:\n        query = query.where(Transaction.account_id == account_id)\n    if category_id is not None:\n        query = query.where(Transaction.category_id == category_id)\n    if tx_type is not None:\n        query = query.where(Transaction.type == tx_type)\n    if date_from is not None:\n        query = query.where(Transaction.date >= date_from)\n    if date_to is not None:\n        query = query.where(Transaction.date <= date_to)\n    if min_amount is not None:\n        query = query.where(Transaction.amount >= min_amount)\n    if max_amount is not None:\n        query = query.where(Transaction.amount <= max_amount)\n    if search:\n        query = query.where(Transaction.description.ilike(f\"%{search}%\"))\n\n    total = db.scalar(select(func.count()).select_from(query.subquery()))\n    items = db.scalars(\n        query.order_by(Transaction.date.desc(), Transaction.id.desc())\n        .limit(limit)\n        .offset(offset)\n    ).all()\n    return list(items), total\n", "app/routers/categories.py": "from fastapi import APIRouter, HTTPException, Response, status\nfrom sqlalchemy import delete, func, select\n\nfrom app.core.deps import CurrentUser, DbSession\nfrom app.models import Budget, Category, Transaction, TransactionType\nfrom app.schemas.category import CategoryCreate, CategoryOut\nfrom app.services.categories import get_user_category\n\nrouter = APIRouter(prefix=\"/categories\", tags=[\"categorías\"])\n\n\n@router.post(\"\", response_model=CategoryOut, status_code=status.HTTP_201_CREATED)\ndef create_category(data: CategoryCreate, user: CurrentUser, db: DbSession):\n    exists = db.scalar(\n        select(Category).where(\n            Category.user_id == user.id,\n            Category.name == data.name,\n            Category.type == data.type,\n        )\n    )\n    if exists:\n        raise HTTPException(status.HTTP_409_CONFLICT, \"Ya existe esa categoría\")\n    category = Category(user_id=user.id, name=data.name, type=data.type)\n    db.add(category)\n    db.commit()\n    db.refresh(category)\n    return category\n\n\n@router.get(\"\", response_model=list[CategoryOut])\ndef list_categories(\n    user: CurrentUser, db: DbSession, type: TransactionType | None = None\n):\n    query = select(Category).where(Category.user_id == user.id).order_by(Category.id)\n    if type is not None:\n        query = query.where(Category.type == type)\n    return db.scalars(query).all()\n\n\n@router.delete(\"/{category_id}\", status_code=status.HTTP_204_NO_CONTENT)\ndef delete_category(category_id: int, user: CurrentUser, db: DbSession):\n    category = get_user_category(db, user.id, category_id)\n    used = db.scalar(\n        select(func.count())\n        .select_from(Transaction)\n        .where(Transaction.category_id == category.id)\n    )\n    if used:\n        raise HTTPException(\n            status.HTTP_409_CONFLICT,\n            \"La categoría tiene movimientos y no puede eliminarse\",\n        )\n    db.execute(delete(Budget).where(Budget.category_id == category.id))\n    db.delete(category)\n    db.commit()\n    return Response(status_code=status.HTTP_204_NO_CONTENT)\n", "app/routers/transactions.py": "import datetime as dt\nfrom decimal import Decimal\n\nfrom fastapi import APIRouter, Query, Response, status\n\nfrom app.core.deps import CurrentUser, DbSession\nfrom app.models import TransactionType\nfrom app.schemas.transaction import (\n    TransactionCreate,\n    TransactionOut,\n    TransactionPage,\n    TransactionUpdate,\n)\nfrom app.services import transactions as service\n\nrouter = APIRouter(prefix=\"/transactions\", tags=[\"movimientos\"])\n\n\n@router.post(\"\", response_model=TransactionOut, status_code=status.HTTP_201_CREATED)\ndef create_transaction(data: TransactionCreate, user: CurrentUser, db: DbSession):\n    \"\"\"Registra manualmente un gasto o ingreso.\"\"\"\n    return service.create_transaction(db, user, data)\n\n\n@router.get(\"\", response_model=TransactionPage)\ndef list_transactions(\n    user: CurrentUser,\n    db: DbSession,\n    account_id: int | None = None,\n    category_id: int | None = None,\n    type: TransactionType | None = None,\n    date_from: dt.date | None = None,\n    date_to: dt.date | None = None,\n    min_amount: Decimal | None = Query(default=None, ge=0),\n    max_amount: Decimal | None = Query(default=None, ge=0),\n    search: str | None = Query(default=None, max_length=100),\n    limit: int = Query(default=50, ge=1, le=200),\n    offset: int = Query(default=0, ge=0),\n):\n    \"\"\"Historial de movimientos, del más reciente al más antiguo, con filtros.\"\"\"\n    items, total = service.search_transactions(\n        db,\n        user.id,\n        account_id=account_id,\n        category_id=category_id,\n        tx_type=type,\n        date_from=date_from,\n        date_to=date_to,\n        min_amount=min_amount,\n        max_amount=max_amount,\n        search=search,\n        limit=limit,\n        offset=offset,\n    )\n    return TransactionPage(items=items, total=total, limit=limit, offset=offset)\n\n\n@router.get(\"/{tx_id}\", response_model=TransactionOut)\ndef get_transaction(tx_id: int, user: CurrentUser, db: DbSession):\n    return service.get_user_transaction(db, user.id, tx_id)\n\n\n@router.patch(\"/{tx_id}\", response_model=TransactionOut)\ndef update_transaction(\n    tx_id: int, data: TransactionUpdate, user: CurrentUser, db: DbSession\n):\n    return service.update_transaction(db, user, tx_id, data)\n\n\n@router.delete(\"/{tx_id}\", status_code=status.HTTP_204_NO_CONTENT)\ndef delete_transaction(tx_id: int, user: CurrentUser, db: DbSession):\n    service.delete_transaction(db, user, tx_id)\n    return Response(status_code=status.HTTP_204_NO_CONTENT)\n", "app/main.py": "from contextlib import asynccontextmanager\n\nfrom fastapi import FastAPI\n\nfrom app import models  # noqa: F401\nfrom app.core.config import settings\nfrom app.core.database import Base, engine\nfrom app.routers import auth\nfrom app.routers import accounts\nfrom app.routers import categories, transactions\n\n\n@asynccontextmanager\nasync def lifespan(app: FastAPI):\n    \"\"\"Crea las tablas de la base de datos al iniciar la aplicación.\"\"\"\n    Base.metadata.create_all(bind=engine)\n    yield\n\n\napp = FastAPI(title=settings.app_name, debug=settings.debug, lifespan=lifespan)\n\napp.include_router(auth.router)\napp.include_router(accounts.router)\napp.include_router(categories.router)\napp.include_router(transactions.router)\n\n\n@app.get(\"/health\", tags=[\"sistema\"])\ndef health():\n    \"\"\"Verifica que la API está en funcionamiento.\"\"\"\n    return {\"status\": \"ok\", \"app\": settings.app_name}\n", "tests/conftest.py": "import pytest\nfrom fastapi.testclient import TestClient\nfrom sqlalchemy import create_engine\nfrom sqlalchemy.orm import sessionmaker\nfrom sqlalchemy.pool import StaticPool\n\nfrom app import models  # noqa: F401\nfrom app.core.database import Base, get_db\nfrom app.main import app\n\n\n@pytest.fixture()\ndef db_session():\n    \"\"\"Base de datos SQLite en memoria, nueva para cada prueba.\"\"\"\n    engine = create_engine(\n        \"sqlite://\",\n        connect_args={\"check_same_thread\": False},\n        poolclass=StaticPool,\n    )\n    Base.metadata.create_all(bind=engine)\n    session = sessionmaker(bind=engine, autoflush=False, autocommit=False)()\n    try:\n        yield session\n    finally:\n        session.close()\n        engine.dispose()\n\n\n@pytest.fixture()\ndef client(db_session):\n    def override_get_db():\n        yield db_session\n\n    app.dependency_overrides[get_db] = override_get_db\n    yield TestClient(app)\n    app.dependency_overrides.clear()\n\n\n@pytest.fixture()\ndef make_headers(client):\n    \"\"\"Entrega una función que registra un usuario y devuelve su encabezado de autenticación.\"\"\"\n\n    def _make(email: str = \"ana@example.com\") -> dict[str, str]:\n        client.post(\n            \"/auth/register\",\n            json={\n                \"email\": email,\n                \"full_name\": \"Ana Pérez\",\n                \"password\": \"Contrasena123\",\n                \"birth_date\": \"1995-05-10\",\n            },\n        )\n        response = client.post(\n            \"/auth/login\", json={\"email\": email, \"password\": \"Contrasena123\"}\n        )\n        return {\"Authorization\": f\"Bearer {response.json()['access_token']}\"}\n\n    return _make\n\n\n@pytest.fixture()\ndef auth_headers(make_headers):\n    return make_headers()\n\n\n@pytest.fixture()\ndef account_id(client, auth_headers):\n    \"\"\"Crea una cuenta con saldo inicial de 1.000.000 y devuelve su id.\"\"\"\n    response = client.post(\n        \"/accounts\",\n        json={\n            \"name\": \"Bancolombia\",\n            \"institution\": \"Bancolombia\",\n            \"account_type\": \"checking\",\n            \"last4\": \"1234\",\n            \"initial_balance\": \"1000000\",\n        },\n        headers=auth_headers,\n    )\n    return response.json()[\"id\"]\n\n\n@pytest.fixture()\ndef categories(client, auth_headers):\n    \"\"\"Diccionario nombre -> id con las categorías por defecto del usuario.\"\"\"\n    items = client.get(\"/categories\", headers=auth_headers).json()\n    return {item[\"name\"]: item[\"id\"] for item in items}\n", "tests/test_transactions.py": "from decimal import Decimal\n\n\ndef crear(client, headers, account_id, category_id, **cambios):\n    payload = {\n        \"account_id\": account_id,\n        \"category_id\": category_id,\n        \"type\": \"expense\",\n        \"amount\": \"50000\",\n        \"description\": \"Almuerzo\",\n        \"date\": \"2026-10-05\",\n    }\n    payload.update(cambios)\n    return client.post(\"/transactions\", json=payload, headers=headers)\n\n\ndef saldo(client, headers, account_id):\n    response = client.get(f\"/accounts/{account_id}\", headers=headers)\n    return Decimal(response.json()[\"balance\"])\n\n\ndef test_categorias_por_defecto(client, auth_headers, categories):\n    assert \"Alimentación\" in categories\n    assert \"Salario\" in categories\n    gastos = client.get(\"/categories?type=expense\", headers=auth_headers).json()\n    assert all(c[\"type\"] == \"expense\" for c in gastos)\n\n\ndef test_crear_categoria_propia_y_duplicada(client, auth_headers):\n    body = {\"name\": \"Mascotas\", \"type\": \"expense\"}\n    assert client.post(\"/categories\", json=body, headers=auth_headers).status_code == 201\n    assert client.post(\"/categories\", json=body, headers=auth_headers).status_code == 409\n\n\ndef test_gasto_e_ingreso_actualizan_el_saldo(client, auth_headers, account_id, categories):\n    crear(client, auth_headers, account_id, categories[\"Alimentación\"], amount=\"50000\")\n    assert saldo(client, auth_headers, account_id) == Decimal(\"950000\")\n\n    crear(\n        client, auth_headers, account_id, categories[\"Salario\"],\n        type=\"income\", amount=\"300000\", description=\"Quincena\",\n    )\n    assert saldo(client, auth_headers, account_id) == Decimal(\"1250000\")\n\n\ndef test_monto_invalido(client, auth_headers, account_id, categories):\n    for monto in (\"0\", \"-5\"):\n        response = crear(client, auth_headers, account_id, categories[\"Alimentación\"], amount=monto)\n        assert response.status_code == 422\n\n\ndef test_categoria_debe_coincidir_con_el_tipo(client, auth_headers, account_id, categories):\n    response = crear(client, auth_headers, account_id, categories[\"Salario\"], type=\"expense\")\n    assert response.status_code == 400\n\n\ndef test_cuenta_o_categoria_inexistente(client, auth_headers, account_id, categories):\n    assert crear(client, auth_headers, 999, categories[\"Alimentación\"]).status_code == 404\n    assert crear(client, auth_headers, account_id, 999).status_code == 404\n\n\ndef test_no_se_puede_registrar_en_cuenta_inactiva(client, auth_headers, account_id, categories):\n    client.patch(f\"/accounts/{account_id}\", json={\"is_active\": False}, headers=auth_headers)\n    response = crear(client, auth_headers, account_id, categories[\"Alimentación\"])\n    assert response.status_code == 400\n\n\ndef test_historial_con_filtros(client, auth_headers, account_id, categories):\n    crear(client, auth_headers, account_id, categories[\"Alimentación\"],\n          amount=\"50000\", date=\"2026-10-05\", description=\"Almuerzo\")\n    crear(client, auth_headers, account_id, categories[\"Transporte\"],\n          amount=\"120000\", date=\"2026-10-10\", description=\"Gasolina\")\n    crear(client, auth_headers, account_id, categories[\"Salario\"],\n          type=\"income\", amount=\"3000000\", date=\"2026-10-01\", description=\"Nómina\")\n\n    def consultar(query):\n        return client.get(f\"/transactions?{query}\", headers=auth_headers).json()\n\n    todos = consultar(\"\")\n    assert todos[\"total\"] == 3\n    # Orden: del más reciente al más antiguo\n    assert [t[\"date\"] for t in todos[\"items\"]] == [\"2026-10-10\", \"2026-10-05\", \"2026-10-01\"]\n\n    assert consultar(\"type=expense\")[\"total\"] == 2\n    assert consultar(\"date_from=2026-10-06\")[\"total\"] == 1\n    assert consultar(\"date_to=2026-10-05\")[\"total\"] == 2\n    assert consultar(\"type=expense&min_amount=100000\")[\"total\"] == 1\n    assert consultar(f\"category_id={categories['Alimentación']}\")[\"total\"] == 1\n    assert consultar(\"search=gasolina\")[\"total\"] == 1\n\n\ndef test_paginacion(client, auth_headers, account_id, categories):\n    for i in range(5):\n        crear(client, auth_headers, account_id, categories[\"Alimentación\"],\n              date=f\"2026-10-0{i + 1}\")\n    pagina = client.get(\"/transactions?limit=2&offset=2\", headers=auth_headers).json()\n    assert pagina[\"total\"] == 5\n    assert len(pagina[\"items\"]) == 2\n\n\ndef test_editar_y_eliminar_movimiento(client, auth_headers, account_id, categories):\n    tx = crear(client, auth_headers, account_id, categories[\"Alimentación\"]).json()\n\n    editado = client.patch(\n        f\"/transactions/{tx['id']}\",\n        json={\"amount\": \"20000\", \"description\": \"Café\"},\n        headers=auth_headers,\n    )\n    assert editado.status_code == 200\n    assert Decimal(editado.json()[\"amount\"]) == Decimal(\"20000\")\n    assert saldo(client, auth_headers, account_id) == Decimal(\"980000\")\n\n    assert client.delete(f\"/transactions/{tx['id']}\", headers=auth_headers).status_code == 204\n    assert client.get(f\"/transactions/{tx['id']}\", headers=auth_headers).status_code == 404\n    assert saldo(client, auth_headers, account_id) == Decimal(\"1000000\")\n\n\ndef test_no_se_elimina_cuenta_ni_categoria_con_movimientos(\n    client, auth_headers, account_id, categories\n):\n    crear(client, auth_headers, account_id, categories[\"Alimentación\"])\n    assert client.delete(f\"/accounts/{account_id}\", headers=auth_headers).status_code == 409\n    assert (\n        client.delete(f\"/categories/{categories['Alimentación']}\", headers=auth_headers).status_code\n        == 409\n    )\n\n\ndef test_un_usuario_no_ve_movimientos_de_otro(\n    client, auth_headers, make_headers, account_id, categories\n):\n    tx = crear(client, auth_headers, account_id, categories[\"Alimentación\"]).json()\n    otro = make_headers(\"luis@example.com\")\n    assert client.get(f\"/transactions/{tx['id']}\", headers=otro).status_code == 404\n    assert client.get(\"/transactions\", headers=otro).json()[\"total\"] == 0\n"}}, "6": {"titulo": "Dashboard y reportes", "commit": "feat: dashboard de resumen y reportes por categoria y periodo", "archivos": {"app/schemas/report.py": "import datetime as dt\nfrom decimal import Decimal\n\nfrom pydantic import BaseModel\n\nfrom app.models.enums import TransactionType\nfrom app.schemas.transaction import TransactionOut\n\n\nclass AccountSummary(BaseModel):\n    id: int\n    name: str\n    currency: str\n    balance: Decimal\n\n\nclass DashboardOut(BaseModel):\n    period_start: dt.date\n    period_end: dt.date\n    total_balance: Decimal\n    income: Decimal\n    expenses: Decimal\n    net: Decimal\n    accounts: list[AccountSummary]\n    recent_transactions: list[TransactionOut]\n    unread_notifications: int\n\n\nclass CategoryReportItem(BaseModel):\n    category_id: int\n    category: str\n    total: Decimal\n    percentage: float\n    count: int\n\n\nclass CategoryReport(BaseModel):\n    date_from: dt.date\n    date_to: dt.date\n    type: TransactionType\n    total: Decimal\n    items: list[CategoryReportItem]\n\n\nclass MonthlyItem(BaseModel):\n    month: int\n    income: Decimal\n    expenses: Decimal\n    net: Decimal\n\n\nclass MonthlyReport(BaseModel):\n    year: int\n    months: list[MonthlyItem]\n\n\nclass InsightsOut(BaseModel):\n    period_start: dt.date\n    period_end: dt.date\n    insights: list[str]\n", "app/services/reports.py": "import calendar\nimport datetime as dt\nimport re\nfrom decimal import Decimal\n\nfrom fastapi import HTTPException, status\nfrom sqlalchemy import func, select\nfrom sqlalchemy.orm import Session\n\nfrom app.core.money import format_money, to_money\nfrom app.models import Category, Transaction, TransactionType\n\n\ndef month_range(\n    month: str | None = None, today: dt.date | None = None\n) -> tuple[dt.date, dt.date]:\n    \"\"\"Primer y último día de un mes dado como 'AAAA-MM' (por defecto, el actual).\"\"\"\n    today = today or dt.date.today()\n    if month is None:\n        year, mon = today.year, today.month\n    else:\n        match = re.fullmatch(r\"(\\d{4})-(\\d{2})\", month)\n        if not match or not 1 <= int(match.group(2)) <= 12:\n            raise HTTPException(\n                status.HTTP_400_BAD_REQUEST, \"Formato de mes inválido, usa AAAA-MM\"\n            )\n        year, mon = int(match.group(1)), int(match.group(2))\n    last_day = calendar.monthrange(year, mon)[1]\n    return dt.date(year, mon, 1), dt.date(year, mon, last_day)\n\n\ndef previous_month(today: dt.date) -> str:\n    year, mon = (today.year - 1, 12) if today.month == 1 else (today.year, today.month - 1)\n    return f\"{year}-{mon:02d}\"\n\n\ndef period_totals(\n    db: Session, user_id: int, date_from: dt.date, date_to: dt.date\n) -> tuple[Decimal, Decimal]:\n    \"\"\"Devuelve (ingresos, gastos) del periodo.\"\"\"\n    rows = db.execute(\n        select(Transaction.type, func.sum(Transaction.amount))\n        .where(\n            Transaction.user_id == user_id,\n            Transaction.date >= date_from,\n            Transaction.date <= date_to,\n        )\n        .group_by(Transaction.type)\n    ).all()\n    totals = {tx_type: to_money(total) for tx_type, total in rows}\n    return (\n        totals.get(TransactionType.income, Decimal(\"0.00\")),\n        totals.get(TransactionType.expense, Decimal(\"0.00\")),\n    )\n\n\ndef by_category(\n    db: Session,\n    user_id: int,\n    date_from: dt.date,\n    date_to: dt.date,\n    tx_type: TransactionType = TransactionType.expense,\n) -> list[tuple[int, str, Decimal, int]]:\n    \"\"\"Totales por categoría, de mayor a menor: (id, nombre, total, cantidad).\"\"\"\n    total_col = func.sum(Transaction.amount)\n    rows = db.execute(\n        select(Category.id, Category.name, total_col, func.count(Transaction.id))\n        .join(Category, Category.id == Transaction.category_id)\n        .where(\n            Transaction.user_id == user_id,\n            Transaction.type == tx_type,\n            Transaction.date >= date_from,\n            Transaction.date <= date_to,\n        )\n        .group_by(Category.id, Category.name)\n        .order_by(total_col.desc())\n    ).all()\n    return [(cid, name, to_money(total), count) for cid, name, total, count in rows]\n\n\ndef spent_in_month(\n    db: Session, user_id: int, category_id: int, ref_date: dt.date\n) -> Decimal:\n    \"\"\"Total gastado en una categoría durante el mes de ref_date.\"\"\"\n    start, end = month_range(f\"{ref_date.year}-{ref_date.month:02d}\")\n    total = db.scalar(\n        select(func.sum(Transaction.amount)).where(\n            Transaction.user_id == user_id,\n            Transaction.category_id == category_id,\n            Transaction.type == TransactionType.expense,\n            Transaction.date >= start,\n            Transaction.date <= end,\n        )\n    )\n    return to_money(total)\n\n\ndef monthly_breakdown(db: Session, user_id: int, year: int) -> list[dict]:\n    \"\"\"Ingresos, gastos y balance de cada mes del año.\"\"\"\n    rows = db.execute(\n        select(Transaction.date, Transaction.type, Transaction.amount).where(\n            Transaction.user_id == user_id,\n            Transaction.date >= dt.date(year, 1, 1),\n            Transaction.date <= dt.date(year, 12, 31),\n        )\n    ).all()\n    months = {m: {\"income\": Decimal(\"0.00\"), \"expenses\": Decimal(\"0.00\")} for m in range(1, 13)}\n    for date, tx_type, amount in rows:\n        key = \"income\" if tx_type == TransactionType.income else \"expenses\"\n        months[date.month][key] += to_money(amount)\n    return [\n        {\"month\": m, **values, \"net\": values[\"income\"] - values[\"expenses\"]}\n        for m, values in months.items()\n    ]\n\n\ndef build_insights(db: Session, user_id: int, today: dt.date | None = None) -> list[str]:\n    \"\"\"Observaciones simples sobre los hábitos de gasto del mes actual.\"\"\"\n    today = today or dt.date.today()\n    start, end = month_range(None, today)\n    income, expenses = period_totals(db, user_id, start, end)\n\n    if income == 0 and expenses == 0:\n        return [\"Aún no tienes movimientos este mes. Registra tus gastos e ingresos para ver tus insights.\"]\n\n    insights: list[str] = []\n\n    top = by_category(db, user_id, start, end)\n    if top and expenses > 0:\n        _, name, total, _ = top[0]\n        pct = round(total / expenses * 100)\n        insights.append(\n            f\"Tu mayor gasto del mes es {name}: {format_money(total)} ({pct}% de tus gastos).\"\n        )\n\n    # Comparación con el mismo tramo del mes anterior\n    prev_start, prev_end = month_range(previous_month(today))\n    same_day = dt.date(prev_end.year, prev_end.month, min(today.day, prev_end.day))\n    _, prev_expenses = period_totals(db, user_id, prev_start, same_day)\n    if prev_expenses > 0:\n        change = (expenses - prev_expenses) / prev_expenses * 100\n        direction = \"más\" if change >= 0 else \"menos\"\n        insights.append(\n            f\"Hasta el día {today.day} llevas un {abs(round(change))}% {direction} de gasto \"\n            f\"que en el mismo periodo del mes pasado.\"\n        )\n\n    if expenses > 0:\n        insights.append(\n            f\"Tu gasto diario promedio este mes es {format_money(expenses / today.day)}.\"\n        )\n\n    if income > 0:\n        saved = income - expenses\n        if saved >= 0:\n            insights.append(f\"Has ahorrado el {round(saved / income * 100)}% de tus ingresos este mes.\")\n        else:\n            insights.append(\n                f\"Tus gastos superan tus ingresos este mes en {format_money(-saved)}.\"\n            )\n    return insights\n", "app/routers/dashboard.py": "from fastapi import APIRouter, Query\nfrom sqlalchemy import func, select\n\nfrom app.core.deps import CurrentUser, DbSession\nfrom app.models import Account, Notification\nfrom app.schemas.report import AccountSummary, DashboardOut\nfrom app.services import reports\nfrom app.services.accounts import compute_balances, total_balance\nfrom app.services.transactions import search_transactions\n\nrouter = APIRouter(prefix=\"/dashboard\", tags=[\"dashboard\"])\n\n\n@router.get(\"\", response_model=DashboardOut)\ndef dashboard(\n    user: CurrentUser,\n    db: DbSession,\n    month: str | None = Query(default=None, description=\"Mes en formato AAAA-MM; por defecto, el actual\"),\n):\n    \"\"\"Resumen: saldo total, ingresos y gastos del periodo, cuentas y últimos movimientos.\"\"\"\n    start, end = reports.month_range(month)\n    income, expenses = reports.period_totals(db, user.id, start, end)\n    balances = compute_balances(db, user.id)\n    accounts = db.scalars(\n        select(Account)\n        .where(Account.user_id == user.id, Account.is_active.is_(True))\n        .order_by(Account.id)\n    ).all()\n    recent, _ = search_transactions(db, user.id, limit=5)\n    unread = db.scalar(\n        select(func.count())\n        .select_from(Notification)\n        .where(Notification.user_id == user.id, Notification.is_read.is_(False))\n    )\n    return DashboardOut(\n        period_start=start,\n        period_end=end,\n        total_balance=total_balance(db, user.id),\n        income=income,\n        expenses=expenses,\n        net=income - expenses,\n        accounts=[\n            AccountSummary(id=a.id, name=a.name, currency=a.currency, balance=balances[a.id])\n            for a in accounts\n        ],\n        recent_transactions=recent,\n        unread_notifications=unread,\n    )\n", "app/routers/reports.py": "import datetime as dt\n\nfrom fastapi import APIRouter, HTTPException, Query, status\n\nfrom app.core.deps import CurrentUser, DbSession\nfrom app.models import TransactionType\nfrom app.schemas.report import (\n    CategoryReport,\n    CategoryReportItem,\n    InsightsOut,\n    MonthlyItem,\n    MonthlyReport,\n)\nfrom app.services import reports\n\nrouter = APIRouter(prefix=\"/reports\", tags=[\"reportes\"])\n\n\n@router.get(\"/by-category\", response_model=CategoryReport)\ndef report_by_category(\n    user: CurrentUser,\n    db: DbSession,\n    date_from: dt.date | None = None,\n    date_to: dt.date | None = None,\n    type: TransactionType = TransactionType.expense,\n):\n    \"\"\"Gasto (o ingreso) por categoría en un periodo; por defecto, el mes actual.\"\"\"\n    default_from, default_to = reports.month_range()\n    date_from = date_from or default_from\n    date_to = date_to or default_to\n    if date_from > date_to:\n        raise HTTPException(\n            status.HTTP_400_BAD_REQUEST, \"date_from no puede ser posterior a date_to\"\n        )\n\n    rows = reports.by_category(db, user.id, date_from, date_to, type)\n    grand_total = sum((total for _, _, total, _ in rows), start=0)\n    items = [\n        CategoryReportItem(\n            category_id=cid,\n            category=name,\n            total=total,\n            percentage=round(float(total / grand_total * 100), 2) if grand_total else 0.0,\n            count=count,\n        )\n        for cid, name, total, count in rows\n    ]\n    return CategoryReport(\n        date_from=date_from,\n        date_to=date_to,\n        type=type,\n        total=grand_total,\n        items=items,\n    )\n\n\n@router.get(\"/monthly\", response_model=MonthlyReport)\ndef report_monthly(\n    user: CurrentUser,\n    db: DbSession,\n    year: int = Query(default_factory=lambda: dt.date.today().year, ge=2000, le=2100),\n):\n    \"\"\"Ingresos, gastos y balance mes a mes de un año.\"\"\"\n    months = reports.monthly_breakdown(db, user.id, year)\n    return MonthlyReport(year=year, months=[MonthlyItem(**m) for m in months])\n\n\n@router.get(\"/insights\", response_model=InsightsOut)\ndef insights(user: CurrentUser, db: DbSession):\n    \"\"\"Observaciones sobre tus patrones de gasto del mes actual.\"\"\"\n    start, end = reports.month_range()\n    return InsightsOut(\n        period_start=start,\n        period_end=end,\n        insights=reports.build_insights(db, user.id),\n    )\n", "app/main.py": "from contextlib import asynccontextmanager\n\nfrom fastapi import FastAPI\n\nfrom app import models  # noqa: F401\nfrom app.core.config import settings\nfrom app.core.database import Base, engine\nfrom app.routers import auth\nfrom app.routers import accounts\nfrom app.routers import categories, transactions\nfrom app.routers import dashboard, reports\n\n\n@asynccontextmanager\nasync def lifespan(app: FastAPI):\n    \"\"\"Crea las tablas de la base de datos al iniciar la aplicación.\"\"\"\n    Base.metadata.create_all(bind=engine)\n    yield\n\n\napp = FastAPI(title=settings.app_name, debug=settings.debug, lifespan=lifespan)\n\napp.include_router(auth.router)\napp.include_router(accounts.router)\napp.include_router(categories.router)\napp.include_router(transactions.router)\napp.include_router(dashboard.router)\napp.include_router(reports.router)\n\n\n@app.get(\"/health\", tags=[\"sistema\"])\ndef health():\n    \"\"\"Verifica que la API está en funcionamiento.\"\"\"\n    return {\"status\": \"ok\", \"app\": settings.app_name}\n", "tests/test_dashboard_reports.py": "import datetime as dt\nfrom decimal import Decimal\n\nHOY = dt.date.today().isoformat()\n\n\ndef crear(client, headers, account_id, category_id, tipo=\"expense\", monto=\"10000\", fecha=HOY):\n    response = client.post(\n        \"/transactions\",\n        json={\n            \"account_id\": account_id,\n            \"category_id\": category_id,\n            \"type\": tipo,\n            \"amount\": monto,\n            \"description\": \"prueba\",\n            \"date\": fecha,\n        },\n        headers=headers,\n    )\n    assert response.status_code == 201, response.text\n    return response.json()\n\n\ndef test_dashboard_resume_el_mes(client, auth_headers, account_id, categories):\n    crear(client, auth_headers, account_id, categories[\"Salario\"], \"income\", \"500000\")\n    crear(client, auth_headers, account_id, categories[\"Alimentación\"], \"expense\", \"200000\")\n\n    body = client.get(\"/dashboard\", headers=auth_headers).json()\n    assert Decimal(body[\"income\"]) == Decimal(\"500000\")\n    assert Decimal(body[\"expenses\"]) == Decimal(\"200000\")\n    assert Decimal(body[\"net\"]) == Decimal(\"300000\")\n    assert Decimal(body[\"total_balance\"]) == Decimal(\"1300000\")\n    assert len(body[\"accounts\"]) == 1\n    assert len(body[\"recent_transactions\"]) == 2\n    assert body[\"unread_notifications\"] == 0\n\n\ndef test_dashboard_mes_especifico_y_formato_invalido(client, auth_headers, account_id, categories):\n    crear(client, auth_headers, account_id, categories[\"Alimentación\"], \"expense\", \"40000\", \"2026-03-15\")\n\n    marzo = client.get(\"/dashboard?month=2026-03\", headers=auth_headers).json()\n    assert Decimal(marzo[\"expenses\"]) == Decimal(\"40000\")\n    assert marzo[\"period_start\"] == \"2026-03-01\"\n    assert marzo[\"period_end\"] == \"2026-03-31\"\n\n    assert client.get(\"/dashboard?month=marzo\", headers=auth_headers).status_code == 400\n    assert client.get(\"/dashboard?month=2026-13\", headers=auth_headers).status_code == 400\n\n\ndef test_dashboard_no_cuenta_cuentas_inactivas(client, auth_headers, account_id):\n    client.patch(f\"/accounts/{account_id}\", json={\"is_active\": False}, headers=auth_headers)\n    body = client.get(\"/dashboard\", headers=auth_headers).json()\n    assert Decimal(body[\"total_balance\"]) == Decimal(\"0\")\n    assert body[\"accounts\"] == []\n\n\ndef test_reporte_por_categoria(client, auth_headers, account_id, categories):\n    crear(client, auth_headers, account_id, categories[\"Alimentación\"], monto=\"30000\")\n    crear(client, auth_headers, account_id, categories[\"Alimentación\"], monto=\"70000\")\n    crear(client, auth_headers, account_id, categories[\"Transporte\"], monto=\"50000\")\n\n    body = client.get(\"/reports/by-category\", headers=auth_headers).json()\n    assert Decimal(body[\"total\"]) == Decimal(\"150000\")\n    assert [i[\"category\"] for i in body[\"items\"]] == [\"Alimentación\", \"Transporte\"]\n    primero = body[\"items\"][0]\n    assert Decimal(primero[\"total\"]) == Decimal(\"100000\")\n    assert primero[\"count\"] == 2\n    assert primero[\"percentage\"] == 66.67\n\n\ndef test_reporte_por_categoria_ingresos_y_rango(client, auth_headers, account_id, categories):\n    crear(client, auth_headers, account_id, categories[\"Salario\"], \"income\", \"900000\", \"2026-01-10\")\n    crear(client, auth_headers, account_id, categories[\"Salario\"], \"income\", \"100000\", \"2026-02-10\")\n\n    body = client.get(\n        \"/reports/by-category?type=income&date_from=2026-01-01&date_to=2026-01-31\",\n        headers=auth_headers,\n    ).json()\n    assert Decimal(body[\"total\"]) == Decimal(\"900000\")\n\n    invalido = client.get(\n        \"/reports/by-category?date_from=2026-02-01&date_to=2026-01-01\", headers=auth_headers\n    )\n    assert invalido.status_code == 400\n\n\ndef test_reporte_mensual(client, auth_headers, account_id, categories):\n    crear(client, auth_headers, account_id, categories[\"Salario\"], \"income\", \"2000000\", \"2026-01-05\")\n    crear(client, auth_headers, account_id, categories[\"Alimentación\"], \"expense\", \"300000\", \"2026-01-20\")\n    crear(client, auth_headers, account_id, categories[\"Alimentación\"], \"expense\", \"100000\", \"2026-03-02\")\n\n    body = client.get(\"/reports/monthly?year=2026\", headers=auth_headers).json()\n    assert len(body[\"months\"]) == 12\n    enero, febrero, marzo = body[\"months\"][0], body[\"months\"][1], body[\"months\"][2]\n    assert Decimal(enero[\"income\"]) == Decimal(\"2000000\")\n    assert Decimal(enero[\"net\"]) == Decimal(\"1700000\")\n    assert Decimal(febrero[\"expenses\"]) == Decimal(\"0\")\n    assert Decimal(marzo[\"expenses\"]) == Decimal(\"100000\")\n\n\ndef test_insights_sin_movimientos(client, auth_headers):\n    body = client.get(\"/reports/insights\", headers=auth_headers).json()\n    assert len(body[\"insights\"]) == 1\n    assert \"Aún no tienes movimientos\" in body[\"insights\"][0]\n\n\ndef test_insights_con_movimientos(client, auth_headers, account_id, categories):\n    crear(client, auth_headers, account_id, categories[\"Salario\"], \"income\", \"1000000\")\n    crear(client, auth_headers, account_id, categories[\"Alimentación\"], \"expense\", \"250000\")\n\n    textos = client.get(\"/reports/insights\", headers=auth_headers).json()[\"insights\"]\n    unido = \" \".join(textos)\n    assert \"Alimentación\" in unido\n    assert \"promedio\" in unido\n    assert \"ahorrado el 75%\" in unido\n\n\ndef test_reportes_requieren_autenticacion(client):\n    assert client.get(\"/dashboard\").status_code == 401\n    assert client.get(\"/reports/by-category\").status_code == 401\n    assert client.get(\"/reports/monthly\").status_code == 401\n    assert client.get(\"/reports/insights\").status_code == 401\n"}}, "7": {"titulo": "Presupuestos y notificaciones", "commit": "feat: presupuestos y notificaciones de alertas de gasto", "archivos": {"app/core/config.py": "from decimal import Decimal\n\nfrom pydantic_settings import BaseSettings, SettingsConfigDict\n\n\nclass Settings(BaseSettings):\n    \"\"\"Configuración de la aplicación, cargada desde variables de entorno o .env.\"\"\"\n\n    app_name: str = \"Finanzas App\"\n    debug: bool = True\n    database_url: str = \"sqlite:///./finanzas.db\"\n    secret_key: str = \"cambia-esta-clave-en-produccion\"\n    algorithm: str = \"HS256\"\n    access_token_expire_minutes: int = 60\n    # Un movimiento igual o mayor a este valor genera una alerta\n    large_transaction_amount: Decimal = Decimal(\"1000000\")\n\n    model_config = SettingsConfigDict(env_file=\".env\", extra=\"ignore\")\n\n\nsettings = Settings()\n", ".env.example": "APP_NAME=Finanzas App\nDEBUG=true\nDATABASE_URL=sqlite:///./finanzas.db\nSECRET_KEY=cambia-esta-clave-en-produccion\nACCESS_TOKEN_EXPIRE_MINUTES=60\nLARGE_TRANSACTION_AMOUNT=1000000\n", "app/schemas/budget.py": "from decimal import Decimal\n\nfrom pydantic import BaseModel, Field\n\n\nclass BudgetCreate(BaseModel):\n    category_id: int\n    monthly_limit: Decimal = Field(gt=0, max_digits=14, decimal_places=2)\n    alert_threshold: Decimal = Field(\n        default=Decimal(\"0.80\"),\n        ge=Decimal(\"0.10\"),\n        le=Decimal(\"1.00\"),\n        max_digits=3,\n        decimal_places=2,\n        description=\"Fracción del límite a partir de la cual se envía una alerta\",\n    )\n\n\nclass BudgetOut(BaseModel):\n    id: int\n    category_id: int\n    category_name: str\n    monthly_limit: Decimal\n    alert_threshold: Decimal\n    spent: Decimal\n    percentage_used: float\n", "app/schemas/notification.py": "import datetime as dt\n\nfrom pydantic import BaseModel, ConfigDict\n\nfrom app.models.enums import NotificationKind\n\n\nclass NotificationOut(BaseModel):\n    model_config = ConfigDict(from_attributes=True)\n\n    id: int\n    kind: NotificationKind\n    message: str\n    is_read: bool\n    created_at: dt.datetime\n", "app/services/notifications.py": "from sqlalchemy import select\nfrom sqlalchemy.orm import Session\n\nfrom app.core.config import settings\nfrom app.core.money import format_money\nfrom app.models import (\n    Budget,\n    Category,\n    Notification,\n    NotificationKind,\n    Transaction,\n    TransactionType,\n    User,\n)\nfrom app.services.reports import spent_in_month\n\n\ndef notify(db: Session, user_id: int, kind: NotificationKind, message: str) -> None:\n    db.add(Notification(user_id=user_id, kind=kind, message=message))\n\n\ndef check_after_transaction(db: Session, user: User, tx: Transaction) -> None:\n    \"\"\"Genera alertas después de registrar un movimiento.\n\n    Debe llamarse con el movimiento ya enviado a la base de datos (flush),\n    para que los totales del mes lo incluyan.\n    \"\"\"\n    if tx.amount >= settings.large_transaction_amount:\n        tipo = \"ingreso\" if tx.type == TransactionType.income else \"gasto\"\n        notify(\n            db,\n            user.id,\n            NotificationKind.large_transaction,\n            f\"Movimiento importante: se registró un {tipo} de {format_money(tx.amount)}.\",\n        )\n\n    if tx.type != TransactionType.expense:\n        return\n\n    budget = db.scalar(\n        select(Budget).where(\n            Budget.user_id == user.id, Budget.category_id == tx.category_id\n        )\n    )\n    if budget is None:\n        return\n\n    category = db.get(Category, tx.category_id)\n    limit = budget.monthly_limit\n    warn_at = limit * budget.alert_threshold\n    spent = spent_in_month(db, user.id, tx.category_id, tx.date)\n    before = spent - tx.amount\n\n    # Solo se alerta al cruzar cada umbral, para no repetir mensajes\n    if spent > limit and before <= limit:\n        notify(\n            db,\n            user.id,\n            NotificationKind.budget_exceeded,\n            f\"Superaste tu presupuesto de {category.name}: llevas \"\n            f\"{format_money(spent)} de {format_money(limit)} este mes.\",\n        )\n    elif warn_at <= spent <= limit and before < warn_at:\n        percent = int(spent / limit * 100)\n        notify(\n            db,\n            user.id,\n            NotificationKind.budget_warning,\n            f\"Alerta: ya usaste el {percent}% de tu presupuesto de {category.name} \"\n            f\"({format_money(spent)} de {format_money(limit)}).\",\n        )\n", "app/services/transactions.py": "import datetime as dt\nfrom decimal import Decimal\n\nfrom fastapi import HTTPException, status\nfrom sqlalchemy import func, select\nfrom sqlalchemy.orm import Session\n\nfrom app.models import Transaction, TransactionType, User\nfrom app.schemas.transaction import TransactionCreate, TransactionUpdate\nfrom app.services import notifications\nfrom app.services.accounts import get_user_account\nfrom app.services.categories import get_user_category\n\n\ndef _validate_refs(\n    db: Session,\n    user_id: int,\n    account_id: int,\n    category_id: int,\n    tx_type: TransactionType,\n    check_active: bool = True,\n) -> None:\n    account = get_user_account(db, user_id, account_id)\n    if check_active and not account.is_active:\n        raise HTTPException(status.HTTP_400_BAD_REQUEST, \"La cuenta está inactiva\")\n    category = get_user_category(db, user_id, category_id)\n    if category.type != tx_type:\n        raise HTTPException(\n            status.HTTP_400_BAD_REQUEST,\n            \"La categoría no corresponde al tipo de movimiento\",\n        )\n\n\ndef get_user_transaction(db: Session, user_id: int, tx_id: int) -> Transaction:\n    tx = db.scalar(\n        select(Transaction).where(Transaction.id == tx_id, Transaction.user_id == user_id)\n    )\n    if tx is None:\n        raise HTTPException(status.HTTP_404_NOT_FOUND, \"Movimiento no encontrado\")\n    return tx\n\n\ndef create_transaction(db: Session, user: User, data: TransactionCreate) -> Transaction:\n    _validate_refs(db, user.id, data.account_id, data.category_id, data.type)\n    tx = Transaction(user_id=user.id, **data.model_dump())\n    db.add(tx)\n    db.flush()\n    notifications.check_after_transaction(db, user, tx)\n    db.commit()\n    db.refresh(tx)\n    return tx\n\n\ndef update_transaction(\n    db: Session, user: User, tx_id: int, data: TransactionUpdate\n) -> Transaction:\n    tx = get_user_transaction(db, user.id, tx_id)\n    changes = data.model_dump(exclude_unset=True, exclude_none=True)\n    merged = {\n        \"account_id\": tx.account_id,\n        \"category_id\": tx.category_id,\n        \"type\": tx.type,\n        **{k: v for k, v in changes.items() if k in (\"account_id\", \"category_id\", \"type\")},\n    }\n    _validate_refs(\n        db,\n        user.id,\n        merged[\"account_id\"],\n        merged[\"category_id\"],\n        merged[\"type\"],\n        check_active=\"account_id\" in changes,\n    )\n    for field, value in changes.items():\n        setattr(tx, field, value)\n    db.commit()\n    db.refresh(tx)\n    return tx\n\n\ndef delete_transaction(db: Session, user: User, tx_id: int) -> None:\n    tx = get_user_transaction(db, user.id, tx_id)\n    db.delete(tx)\n    db.commit()\n\n\ndef search_transactions(\n    db: Session,\n    user_id: int,\n    *,\n    account_id: int | None = None,\n    category_id: int | None = None,\n    tx_type: TransactionType | None = None,\n    date_from: dt.date | None = None,\n    date_to: dt.date | None = None,\n    min_amount: Decimal | None = None,\n    max_amount: Decimal | None = None,\n    search: str | None = None,\n    limit: int = 50,\n    offset: int = 0,\n) -> tuple[list[Transaction], int]:\n    \"\"\"Historial de movimientos con filtros. Devuelve (movimientos, total).\"\"\"\n    query = select(Transaction).where(Transaction.user_id == user_id)\n    if account_id is not None:\n        query = query.where(Transaction.account_id == account_id)\n    if category_id is not None:\n        query = query.where(Transaction.category_id == category_id)\n    if tx_type is not None:\n        query = query.where(Transaction.type == tx_type)\n    if date_from is not None:\n        query = query.where(Transaction.date >= date_from)\n    if date_to is not None:\n        query = query.where(Transaction.date <= date_to)\n    if min_amount is not None:\n        query = query.where(Transaction.amount >= min_amount)\n    if max_amount is not None:\n        query = query.where(Transaction.amount <= max_amount)\n    if search:\n        query = query.where(Transaction.description.ilike(f\"%{search}%\"))\n\n    total = db.scalar(select(func.count()).select_from(query.subquery()))\n    items = db.scalars(\n        query.order_by(Transaction.date.desc(), Transaction.id.desc())\n        .limit(limit)\n        .offset(offset)\n    ).all()\n    return list(items), total\n", "app/routers/budgets.py": "import datetime as dt\n\nfrom fastapi import APIRouter, HTTPException, Response, status\nfrom sqlalchemy import select\n\nfrom app.core.deps import CurrentUser, DbSession\nfrom app.core.money import to_money\nfrom app.models import Budget, Category, TransactionType\nfrom app.schemas.budget import BudgetCreate, BudgetOut\nfrom app.services.categories import get_user_category\nfrom app.services.reports import spent_in_month\n\nrouter = APIRouter(prefix=\"/budgets\", tags=[\"presupuestos\"])\n\n\ndef _to_out(db, user_id: int, budget: Budget, category: Category) -> BudgetOut:\n    spent = spent_in_month(db, user_id, budget.category_id, dt.date.today())\n    limit = to_money(budget.monthly_limit)\n    return BudgetOut(\n        id=budget.id,\n        category_id=budget.category_id,\n        category_name=category.name,\n        monthly_limit=limit,\n        alert_threshold=budget.alert_threshold,\n        spent=spent,\n        percentage_used=round(float(spent / limit * 100), 2),\n    )\n\n\n@router.post(\"\", response_model=BudgetOut, status_code=status.HTTP_201_CREATED)\ndef create_budget(data: BudgetCreate, user: CurrentUser, db: DbSession):\n    \"\"\"Define un límite mensual de gasto para una categoría.\"\"\"\n    category = get_user_category(db, user.id, data.category_id)\n    if category.type != TransactionType.expense:\n        raise HTTPException(\n            status.HTTP_400_BAD_REQUEST,\n            \"Solo se pueden crear presupuestos para categorías de gasto\",\n        )\n    exists = db.scalar(\n        select(Budget).where(Budget.user_id == user.id, Budget.category_id == category.id)\n    )\n    if exists:\n        raise HTTPException(\n            status.HTTP_409_CONFLICT, \"Ya existe un presupuesto para esa categoría\"\n        )\n    budget = Budget(user_id=user.id, **data.model_dump())\n    db.add(budget)\n    db.commit()\n    db.refresh(budget)\n    return _to_out(db, user.id, budget, category)\n\n\n@router.get(\"\", response_model=list[BudgetOut])\ndef list_budgets(user: CurrentUser, db: DbSession):\n    rows = db.execute(\n        select(Budget, Category)\n        .join(Category, Category.id == Budget.category_id)\n        .where(Budget.user_id == user.id)\n        .order_by(Budget.id)\n    ).all()\n    return [_to_out(db, user.id, budget, category) for budget, category in rows]\n\n\n@router.delete(\"/{budget_id}\", status_code=status.HTTP_204_NO_CONTENT)\ndef delete_budget(budget_id: int, user: CurrentUser, db: DbSession):\n    budget = db.scalar(\n        select(Budget).where(Budget.id == budget_id, Budget.user_id == user.id)\n    )\n    if budget is None:\n        raise HTTPException(status.HTTP_404_NOT_FOUND, \"Presupuesto no encontrado\")\n    db.delete(budget)\n    db.commit()\n    return Response(status_code=status.HTTP_204_NO_CONTENT)\n", "app/routers/notifications.py": "from fastapi import APIRouter, HTTPException, status\nfrom sqlalchemy import select, update\n\nfrom app.core.deps import CurrentUser, DbSession\nfrom app.models import Notification\nfrom app.schemas.notification import NotificationOut\n\nrouter = APIRouter(prefix=\"/notifications\", tags=[\"notificaciones\"])\n\n\n@router.get(\"\", response_model=list[NotificationOut])\ndef list_notifications(user: CurrentUser, db: DbSession, unread_only: bool = False):\n    query = select(Notification).where(Notification.user_id == user.id)\n    if unread_only:\n        query = query.where(Notification.is_read.is_(False))\n    return db.scalars(query.order_by(Notification.id.desc())).all()\n\n\n@router.post(\"/read-all\")\ndef mark_all_read(user: CurrentUser, db: DbSession):\n    result = db.execute(\n        update(Notification)\n        .where(Notification.user_id == user.id, Notification.is_read.is_(False))\n        .values(is_read=True)\n    )\n    db.commit()\n    return {\"updated\": result.rowcount}\n\n\n@router.post(\"/{notification_id}/read\", response_model=NotificationOut)\ndef mark_read(notification_id: int, user: CurrentUser, db: DbSession):\n    notification = db.scalar(\n        select(Notification).where(\n            Notification.id == notification_id, Notification.user_id == user.id\n        )\n    )\n    if notification is None:\n        raise HTTPException(status.HTTP_404_NOT_FOUND, \"Notificación no encontrada\")\n    notification.is_read = True\n    db.commit()\n    db.refresh(notification)\n    return notification\n", "app/main.py": "from contextlib import asynccontextmanager\n\nfrom fastapi import FastAPI\n\nfrom app import models  # noqa: F401\nfrom app.core.config import settings\nfrom app.core.database import Base, engine\nfrom app.routers import auth\nfrom app.routers import accounts\nfrom app.routers import categories, transactions\nfrom app.routers import dashboard, reports\nfrom app.routers import budgets, notifications\n\n\n@asynccontextmanager\nasync def lifespan(app: FastAPI):\n    \"\"\"Crea las tablas de la base de datos al iniciar la aplicación.\"\"\"\n    Base.metadata.create_all(bind=engine)\n    yield\n\n\napp = FastAPI(title=settings.app_name, debug=settings.debug, lifespan=lifespan)\n\napp.include_router(auth.router)\napp.include_router(accounts.router)\napp.include_router(categories.router)\napp.include_router(transactions.router)\napp.include_router(dashboard.router)\napp.include_router(reports.router)\napp.include_router(budgets.router)\napp.include_router(notifications.router)\n\n\n@app.get(\"/health\", tags=[\"sistema\"])\ndef health():\n    \"\"\"Verifica que la API está en funcionamiento.\"\"\"\n    return {\"status\": \"ok\", \"app\": settings.app_name}\n", "tests/test_budgets_notifications.py": "import datetime as dt\nfrom decimal import Decimal\n\nHOY = dt.date.today().isoformat()\n\n\ndef gastar(client, headers, account_id, category_id, monto):\n    response = client.post(\n        \"/transactions\",\n        json={\n            \"account_id\": account_id,\n            \"category_id\": category_id,\n            \"type\": \"expense\",\n            \"amount\": str(monto),\n            \"description\": \"prueba\",\n            \"date\": HOY,\n        },\n        headers=headers,\n    )\n    assert response.status_code == 201, response.text\n\n\ndef notificaciones(client, headers, **params):\n    query = \"&\".join(f\"{k}={v}\" for k, v in params.items())\n    return client.get(f\"/notifications?{query}\", headers=headers).json()\n\n\ndef crear_presupuesto(client, headers, category_id, limite=\"100000\", **extra):\n    return client.post(\n        \"/budgets\",\n        json={\"category_id\": category_id, \"monthly_limit\": limite, **extra},\n        headers=headers,\n    )\n\n\ndef test_crear_y_listar_presupuesto(client, auth_headers, account_id, categories):\n    response = crear_presupuesto(client, auth_headers, categories[\"Alimentación\"])\n    assert response.status_code == 201\n    assert response.json()[\"category_name\"] == \"Alimentación\"\n\n    gastar(client, auth_headers, account_id, categories[\"Alimentación\"], 25000)\n    lista = client.get(\"/budgets\", headers=auth_headers).json()\n    assert len(lista) == 1\n    assert Decimal(lista[0][\"spent\"]) == Decimal(\"25000\")\n    assert lista[0][\"percentage_used\"] == 25.0\n\n\ndef test_presupuesto_invalido(client, auth_headers, categories):\n    # Duplicado\n    crear_presupuesto(client, auth_headers, categories[\"Alimentación\"])\n    assert crear_presupuesto(client, auth_headers, categories[\"Alimentación\"]).status_code == 409\n    # Categoría de ingreso\n    assert crear_presupuesto(client, auth_headers, categories[\"Salario\"]).status_code == 400\n    # Límite inválido\n    assert crear_presupuesto(client, auth_headers, categories[\"Transporte\"], limite=\"0\").status_code == 422\n    # Categoría inexistente\n    assert crear_presupuesto(client, auth_headers, 999).status_code == 404\n\n\ndef test_eliminar_presupuesto(client, auth_headers, categories):\n    budget = crear_presupuesto(client, auth_headers, categories[\"Alimentación\"]).json()\n    assert client.delete(f\"/budgets/{budget['id']}\", headers=auth_headers).status_code == 204\n    assert client.delete(f\"/budgets/{budget['id']}\", headers=auth_headers).status_code == 404\n    assert client.get(\"/budgets\", headers=auth_headers).json() == []\n\n\ndef test_alertas_al_acercarse_y_superar_el_limite(client, auth_headers, account_id, categories):\n    alimentacion = categories[\"Alimentación\"]\n    crear_presupuesto(client, auth_headers, alimentacion, limite=\"100000\")\n\n    gastar(client, auth_headers, account_id, alimentacion, 50000)  # 50%\n    assert notificaciones(client, auth_headers) == []\n\n    gastar(client, auth_headers, account_id, alimentacion, 35000)  # 85% -> aviso\n    lista = notificaciones(client, auth_headers)\n    assert [n[\"kind\"] for n in lista] == [\"budget_warning\"]\n    assert \"85%\" in lista[0][\"message\"]\n\n    gastar(client, auth_headers, account_id, alimentacion, 5000)  # 90% -> sin nuevo aviso\n    assert len(notificaciones(client, auth_headers)) == 1\n\n    gastar(client, auth_headers, account_id, alimentacion, 20000)  # 110% -> superado\n    kinds = [n[\"kind\"] for n in notificaciones(client, auth_headers)]\n    assert kinds == [\"budget_exceeded\", \"budget_warning\"]\n\n    gastar(client, auth_headers, account_id, alimentacion, 1000)  # sigue superado, sin repetir\n    assert len(notificaciones(client, auth_headers)) == 2\n\n\ndef test_un_solo_gasto_que_supera_el_limite(client, auth_headers, account_id, categories):\n    crear_presupuesto(client, auth_headers, categories[\"Transporte\"], limite=\"50000\")\n    gastar(client, auth_headers, account_id, categories[\"Transporte\"], 80000)\n    kinds = [n[\"kind\"] for n in notificaciones(client, auth_headers)]\n    assert kinds == [\"budget_exceeded\"]\n\n\ndef test_sin_presupuesto_no_hay_alertas(client, auth_headers, account_id, categories):\n    gastar(client, auth_headers, account_id, categories[\"Alimentación\"], 500000)\n    assert notificaciones(client, auth_headers) == []\n\n\ndef test_alerta_por_movimiento_grande(client, auth_headers, account_id, categories):\n    gastar(client, auth_headers, account_id, categories[\"Vivienda\"], 1500000)\n    lista = notificaciones(client, auth_headers)\n    assert [n[\"kind\"] for n in lista] == [\"large_transaction\"]\n    assert \"$1.500.000\" in lista[0][\"message\"]\n\n\ndef test_marcar_notificaciones_como_leidas(client, auth_headers, account_id, categories):\n    gastar(client, auth_headers, account_id, categories[\"Vivienda\"], 1200000)\n    gastar(client, auth_headers, account_id, categories[\"Salud\"], 1300000)\n\n    assert len(notificaciones(client, auth_headers, unread_only=\"true\")) == 2\n    dashboard = client.get(\"/dashboard\", headers=auth_headers).json()\n    assert dashboard[\"unread_notifications\"] == 2\n\n    primera = notificaciones(client, auth_headers)[0][\"id\"]\n    response = client.post(f\"/notifications/{primera}/read\", headers=auth_headers)\n    assert response.json()[\"is_read\"] is True\n    assert len(notificaciones(client, auth_headers, unread_only=\"true\")) == 1\n\n    todas = client.post(\"/notifications/read-all\", headers=auth_headers).json()\n    assert todas == {\"updated\": 1}\n    assert notificaciones(client, auth_headers, unread_only=\"true\") == []\n\n\ndef test_notificaciones_son_privadas(client, auth_headers, make_headers, account_id, categories):\n    gastar(client, auth_headers, account_id, categories[\"Vivienda\"], 1500000)\n    nid = notificaciones(client, auth_headers)[0][\"id\"]\n\n    otro = make_headers(\"luis@example.com\")\n    assert notificaciones(client, otro) == []\n    assert client.post(f\"/notifications/{nid}/read\", headers=otro).status_code == 404\n"}}, "8": {"titulo": "Bot de lenguaje natural", "commit": "feat: bot de lenguaje natural y documentacion final", "archivos": {"app/schemas/bot.py": "from typing import Any\n\nfrom pydantic import BaseModel, Field\n\n\nclass BotMessage(BaseModel):\n    text: str = Field(min_length=1, max_length=500)\n\n\nclass BotReply(BaseModel):\n    reply: str\n    action: str\n    data: dict[str, Any] | None = None\n", "app/services/bot.py": "\"\"\"Bot de lenguaje natural.\n\nInterpreta mensajes en español con reglas simples (sin servicios externos) y\nejecuta las mismas operaciones que el usuario haría en la aplicación:\nregistrar gastos e ingresos, consultar saldo, movimientos y resúmenes.\n\"\"\"\nimport datetime as dt\nimport re\nimport unicodedata\nfrom decimal import Decimal, InvalidOperation\n\nfrom pydantic import ValidationError\nfrom sqlalchemy import select\nfrom sqlalchemy.orm import Session\n\nfrom app.core.money import format_money, to_money\nfrom app.models import Account, Category, TransactionType, User\nfrom app.schemas.bot import BotReply\nfrom app.schemas.transaction import TransactionCreate\nfrom app.services import reports\nfrom app.services.accounts import compute_balances, total_balance\nfrom app.services.transactions import create_transaction, search_transactions\n\nHELP_TEXT = (\n    \"Puedo ayudarte con cosas como:\\n\"\n    \"- «gasté 20.000 en almuerzo» o «pagué 80k de arriendo con Nequi»\\n\"\n    \"- «recibí 1.500.000 de salario»\\n\"\n    \"- «cuánto tengo» (saldo)\\n\"\n    \"- «cuánto gasté en comida este mes»\\n\"\n    \"- «últimos movimientos»\\n\"\n    \"- «resumen»\"\n)\n\nAMOUNT_RE = re.compile(r\"(?<![\\w.,])(\\d+(?:[.,]\\d+)*)\\s*(millones|millon|mil|k)?(?!\\w)\")\nINCOME_RE = re.compile(\n    r\"\\b(recibi|me pagaron|me pagan|me llego|me consignaron|me depositaron|gane|cobre|ingreso|ingrese)\\b\"\n)\nEXPENSE_RE = re.compile(r\"\\b(gaste|pague|compre|gasto|pago|me cobraron)\\b\")\n\nMULTIPLIERS = {\"k\": 1_000, \"mil\": 1_000, \"millon\": 1_000_000, \"millones\": 1_000_000}\n\n# Palabras que sugieren una categoría (clave = nombre normalizado de la categoría)\nSYNONYMS = {\n    \"alimentacion\": [\"comida\", \"mercado\", \"restaurante\", \"almuerzo\", \"cena\", \"desayuno\",\n                     \"supermercado\", \"domicilio\", \"cafe\", \"snack\"],\n    \"transporte\": [\"bus\", \"taxi\", \"uber\", \"gasolina\", \"metro\", \"pasaje\", \"transporte\", \"parqueadero\"],\n    \"vivienda\": [\"arriendo\", \"renta\", \"alquiler\", \"hipoteca\", \"administracion\"],\n    \"servicios\": [\"luz\", \"agua\", \"internet\", \"gas\", \"celular\", \"telefono\", \"servicios\"],\n    \"salud\": [\"medico\", \"doctor\", \"medicina\", \"medicinas\", \"farmacia\", \"drogueria\", \"salud\"],\n    \"educacion\": [\"matricula\", \"curso\", \"universidad\", \"libros\", \"educacion\"],\n    \"entretenimiento\": [\"cine\", \"netflix\", \"spotify\", \"juego\", \"fiesta\", \"concierto\", \"entretenimiento\"],\n    \"ropa\": [\"ropa\", \"zapatos\", \"camisa\", \"pantalon\"],\n    \"salario\": [\"salario\", \"sueldo\", \"nomina\", \"quincena\"],\n    \"ventas\": [\"venta\", \"ventas\", \"vendi\"],\n}\n\n\ndef normalize(text: str) -> str:\n    \"\"\"Minúsculas, sin tildes y con espacios simples.\"\"\"\n    text = unicodedata.normalize(\"NFD\", text.lower())\n    text = \"\".join(c for c in text if unicodedata.category(c) != \"Mn\")\n    return re.sub(r\"\\s+\", \" \", text).strip()\n\n\ndef parse_amount(text: str) -> Decimal | None:\n    \"\"\"Extrae el primer monto del texto: 20.000, 20k, 2 mil, 1,5 millones...\"\"\"\n    match = AMOUNT_RE.search(normalize(text))\n    if not match:\n        return None\n    raw, suffix = match.groups()\n    if re.fullmatch(r\"\\d{1,3}([.,]\\d{3})+\", raw):\n        number = Decimal(re.sub(r\"[.,]\", \"\", raw))  # separadores de miles\n    else:\n        try:\n            number = Decimal(raw.replace(\",\", \".\"))\n        except InvalidOperation:\n            return None\n    if suffix:\n        number *= MULTIPLIERS[suffix]\n    return to_money(number) if number > 0 else None\n\n\ndef _has_word(text: str, word: str) -> bool:\n    return re.search(rf\"\\b{re.escape(word)}\\b\", text) is not None\n\n\ndef detect_intent(t: str) -> str:\n    if \"cuanto\" in t and re.search(r\"\\bgast\\w*\", t):\n        return \"spending\"\n    if any(p in t for p in (\"saldo\", \"cuanto tengo\", \"cuanta plata tengo\", \"cuanto dinero tengo\", \"balance\")):\n        return \"balance\"\n    if any(p in t for p in (\"ultimos movimientos\", \"ultimas transacciones\", \"ultimos gastos\",\n                            \"movimientos recientes\", \"historial\")):\n        return \"recent\"\n    if any(p in t for p in (\"resumen\", \"como voy\", \"como van mis finanzas\")):\n        return \"summary\"\n    if INCOME_RE.search(t):\n        return \"income\"\n    if EXPENSE_RE.search(t):\n        return \"expense\"\n    return \"help\"\n\n\ndef _user_categories(db: Session, user_id: int, tx_type: TransactionType) -> list[Category]:\n    return list(\n        db.scalars(\n            select(Category)\n            .where(Category.user_id == user_id, Category.type == tx_type)\n            .order_by(Category.id)\n        )\n    )\n\n\ndef find_category(\n    db: Session, user_id: int, t: str, tx_type: TransactionType\n) -> Category | None:\n    categories = _user_categories(db, user_id, tx_type)\n    by_name = {normalize(c.name): c for c in categories}\n    for name, category in by_name.items():\n        if _has_word(t, name):\n            return category\n    for name, words in SYNONYMS.items():\n        if name in by_name and any(_has_word(t, w) for w in words):\n            return by_name[name]\n    return None\n\n\ndef fallback_category(db: Session, user_id: int, tx_type: TransactionType) -> Category | None:\n    categories = _user_categories(db, user_id, tx_type)\n    for category in categories:\n        if normalize(category.name).startswith(\"otros\"):\n            return category\n    return categories[0] if categories else None\n\n\ndef find_account(db: Session, user_id: int, t: str) -> tuple[Account | None, list[Account]]:\n    accounts = list(\n        db.scalars(\n            select(Account)\n            .where(Account.user_id == user_id, Account.is_active.is_(True))\n            .order_by(Account.id)\n        )\n    )\n    for account in accounts:\n        for candidate in (account.name, account.institution):\n            name = normalize(candidate or \"\")\n            if name and _has_word(t, name):\n                return account, accounts\n    if len(accounts) == 1:\n        return accounts[0], accounts\n    return None, accounts\n\n\ndef _period(t: str, today: dt.date) -> tuple[dt.date, dt.date, str]:\n    if _has_word(t, \"hoy\"):\n        return today, today, \"hoy\"\n    if _has_word(t, \"ayer\"):\n        yesterday = today - dt.timedelta(days=1)\n        return yesterday, yesterday, \"ayer\"\n    if _has_word(t, \"semana\"):\n        return today - dt.timedelta(days=today.weekday()), today, \"esta semana\"\n    if \"mes pasado\" in t:\n        start, end = reports.month_range(reports.previous_month(today), today)\n        return start, end, \"el mes pasado\"\n    start, end = reports.month_range(None, today)\n    return start, end, \"este mes\"\n\n\ndef _register(db: Session, user: User, text: str, t: str, tx_type: TransactionType) -> BotReply:\n    amount = parse_amount(text)\n    if amount is None:\n        return BotReply(\n            action=\"needs_info\",\n            reply=\"No encontré el monto. Prueba por ejemplo: «gasté 20.000 en comida».\",\n        )\n\n    account, accounts = find_account(db, user.id, t)\n    if not accounts:\n        return BotReply(\n            action=\"needs_info\",\n            reply=\"Primero debes vincular una cuenta para poder registrar movimientos.\",\n        )\n    if account is None:\n        nombres = \", \".join(a.name for a in accounts)\n        return BotReply(\n            action=\"needs_info\",\n            reply=f\"¿En cuál cuenta? Tus cuentas son: {nombres}. \"\n            \"Repite el mensaje mencionándola, por ejemplo: «... con \" + accounts[0].name + \"».\",\n        )\n\n    category = find_category(db, user.id, t, tx_type) or fallback_category(db, user.id, tx_type)\n    if category is None:\n        return BotReply(action=\"needs_info\", reply=\"No tienes categorías de ese tipo creadas.\")\n\n    when = dt.date.today() - dt.timedelta(days=1) if _has_word(t, \"ayer\") else dt.date.today()\n    try:\n        data = TransactionCreate(\n            account_id=account.id,\n            category_id=category.id,\n            type=tx_type,\n            amount=amount,\n            description=text.strip()[:255],\n            date=when,\n        )\n    except ValidationError:\n        return BotReply(action=\"needs_info\", reply=\"El monto indicado no es válido.\")\n\n    tx = create_transaction(db, user, data)\n    kind = \"gasto\" if tx_type == TransactionType.expense else \"ingreso\"\n    return BotReply(\n        action=\"transaction_created\",\n        reply=f\"Listo, registré un {kind} de {format_money(amount)} en {category.name} \"\n        f\"(cuenta {account.name}).\",\n        data={\n            \"transaction_id\": tx.id,\n            \"type\": tx_type.value,\n            \"amount\": str(amount),\n            \"category\": category.name,\n            \"account\": account.name,\n            \"date\": when.isoformat(),\n        },\n    )\n\n\ndef _balance(db: Session, user: User) -> BotReply:\n    accounts = list(\n        db.scalars(\n            select(Account)\n            .where(Account.user_id == user.id, Account.is_active.is_(True))\n            .order_by(Account.id)\n        )\n    )\n    if not accounts:\n        return BotReply(action=\"balance\", reply=\"Aún no tienes cuentas vinculadas.\")\n    balances = compute_balances(db, user.id)\n    lines = [f\"Tu saldo total es {format_money(total_balance(db, user.id))}.\"]\n    lines += [f\"- {a.name}: {format_money(balances[a.id])}\" for a in accounts]\n    return BotReply(action=\"balance\", reply=\"\\n\".join(lines))\n\n\ndef _spending(db: Session, user: User, t: str) -> BotReply:\n    today = dt.date.today()\n    start, end, label = _period(t, today)\n    category = find_category(db, user.id, t, TransactionType.expense)\n    rows = reports.by_category(db, user.id, start, end, TransactionType.expense)\n    if category is not None:\n        total = next((r[2] for r in rows if r[0] == category.id), to_money(0))\n        reply = f\"Gastaste {format_money(total)} en {category.name} {label}.\"\n    else:\n        total = sum((r[2] for r in rows), start=to_money(0))\n        reply = f\"Gastaste {format_money(total)} en total {label}.\"\n    return BotReply(action=\"spending\", reply=reply, data={\"total\": str(total)})\n\n\ndef _recent(db: Session, user: User) -> BotReply:\n    items, _ = search_transactions(db, user.id, limit=5)\n    if not items:\n        return BotReply(action=\"recent\", reply=\"Aún no tienes movimientos registrados.\")\n    lines = [\"Tus últimos movimientos:\"]\n    for tx in items:\n        kind = \"gasto\" if tx.type == TransactionType.expense else \"ingreso\"\n        detail = f\" · {tx.description}\" if tx.description else \"\"\n        lines.append(f\"- {tx.date.isoformat()} · {kind} · {format_money(tx.amount)}{detail}\")\n    return BotReply(action=\"recent\", reply=\"\\n\".join(lines))\n\n\ndef _summary(db: Session, user: User) -> BotReply:\n    start, end = reports.month_range()\n    income, expenses = reports.period_totals(db, user.id, start, end)\n    lines = [\n        f\"Resumen de este mes: ingresos {format_money(income)}, \"\n        f\"gastos {format_money(expenses)}, balance {format_money(income - expenses)}.\"\n    ]\n    top = reports.by_category(db, user.id, start, end)\n    if top:\n        lines.append(f\"Tu mayor gasto es {top[0][1]} ({format_money(top[0][2])}).\")\n    return BotReply(action=\"summary\", reply=\"\\n\".join(lines))\n\n\ndef handle_message(db: Session, user: User, text: str) -> BotReply:\n    \"\"\"Interpreta el mensaje del usuario y ejecuta la acción correspondiente.\"\"\"\n    t = normalize(text)\n    intent = detect_intent(t)\n    if intent == \"spending\":\n        return _spending(db, user, t)\n    if intent == \"balance\":\n        return _balance(db, user)\n    if intent == \"recent\":\n        return _recent(db, user)\n    if intent == \"summary\":\n        return _summary(db, user)\n    if intent == \"income\":\n        return _register(db, user, text, t, TransactionType.income)\n    if intent == \"expense\":\n        return _register(db, user, text, t, TransactionType.expense)\n    return BotReply(action=\"help\", reply=HELP_TEXT)\n", "app/routers/bot.py": "from fastapi import APIRouter\n\nfrom app.core.deps import CurrentUser, DbSession\nfrom app.schemas.bot import BotMessage, BotReply\nfrom app.services.bot import handle_message\n\nrouter = APIRouter(prefix=\"/bot\", tags=[\"bot\"])\n\n\n@router.post(\"/message\", response_model=BotReply)\ndef send_message(message: BotMessage, user: CurrentUser, db: DbSession):\n    \"\"\"Ejecuta operaciones con lenguaje natural, por ejemplo «gasté 20.000 en comida».\"\"\"\n    return handle_message(db, user, message.text)\n", "app/main.py": "from contextlib import asynccontextmanager\n\nfrom fastapi import FastAPI\n\nfrom app import models  # noqa: F401\nfrom app.core.config import settings\nfrom app.core.database import Base, engine\nfrom app.routers import auth\nfrom app.routers import accounts\nfrom app.routers import categories, transactions\nfrom app.routers import dashboard, reports\nfrom app.routers import budgets, notifications\nfrom app.routers import bot\n\n\n@asynccontextmanager\nasync def lifespan(app: FastAPI):\n    \"\"\"Crea las tablas de la base de datos al iniciar la aplicación.\"\"\"\n    Base.metadata.create_all(bind=engine)\n    yield\n\n\napp = FastAPI(title=settings.app_name, debug=settings.debug, lifespan=lifespan)\n\napp.include_router(auth.router)\napp.include_router(accounts.router)\napp.include_router(categories.router)\napp.include_router(transactions.router)\napp.include_router(dashboard.router)\napp.include_router(reports.router)\napp.include_router(budgets.router)\napp.include_router(notifications.router)\napp.include_router(bot.router)\n\n\n@app.get(\"/health\", tags=[\"sistema\"])\ndef health():\n    \"\"\"Verifica que la API está en funcionamiento.\"\"\"\n    return {\"status\": \"ok\", \"app\": settings.app_name}\n", "README.md": "# Finanzas App\n\nAPI para centralizar las finanzas personales: vincular cuentas bancarias,\nregistrar gastos e ingresos, ver un resumen general, consultar el historial,\nobtener reportes y recibir alertas de gasto. Incluye un bot que entiende\nmensajes en español como «gasté 20.000 en almuerzo».\n\nDirigida a usuarios adultos (18+) con varias cuentas bancarias.\n\n## Funcionalidades\n\n| Funcionalidad | Endpoints |\n|---|---|\n| Registro y sesión (JWT) | `POST /auth/register`, `POST /auth/login`, `GET /auth/me` |\n| Vinculación de cuentas | `POST/GET /accounts`, `GET/PATCH/DELETE /accounts/{id}` |\n| Categorías | `POST/GET /categories`, `DELETE /categories/{id}` |\n| Registro de movimientos | `POST /transactions`, `PATCH/DELETE /transactions/{id}` |\n| Historial con filtros | `GET /transactions` (cuenta, categoría, tipo, fechas, monto, texto, paginación) |\n| Dashboard de resumen | `GET /dashboard?month=AAAA-MM` |\n| Reportes y análisis | `GET /reports/by-category`, `GET /reports/monthly`, `GET /reports/insights` |\n| Presupuestos | `POST/GET /budgets`, `DELETE /budgets/{id}` |\n| Notificaciones | `GET /notifications`, `POST /notifications/{id}/read`, `POST /notifications/read-all` |\n| Bot de automatización | `POST /bot/message` |\n\n## Stack\n\n- Python 3.11+\n- FastAPI\n- SQLAlchemy 2.0 + SQLite\n- JWT (PyJWT) y contraseñas con PBKDF2-SHA256\n- Pytest\n\n## Instalación\n\n```bash\npython -m venv .venv\nsource .venv/bin/activate   # En Windows: .venv\\Scripts\\activate\npip install -r requirements.txt\ncp .env.example .env        # En Windows: copy .env.example .env\n```\n\nCambia `SECRET_KEY` en `.env` por un valor propio antes de usar la app de verdad.\n\n## Ejecución\n\n```bash\nuvicorn app.main:app --reload\n```\n\nDocumentación interactiva: http://127.0.0.1:8000/docs\n\nPara probar los endpoints protegidos: registra un usuario, haz login, copia el\n`access_token` y pégalo en el botón **Authorize** de la documentación.\n\n## Bot\n\nEnvía mensajes a `POST /bot/message`:\n\n```json\n{ \"text\": \"gasté 20.000 en almuerzo\" }\n```\n\nEjemplos que entiende:\n\n- `gasté 20.000 en almuerzo`, `pagué 80k de arriendo con Nequi`, `ayer gasté 3000 en bus`\n- `recibí 1.500.000 de salario`\n- `cuánto tengo`\n- `cuánto gasté en comida este mes`\n- `últimos movimientos`\n- `resumen`\n\nSi tienes varias cuentas y no mencionas cuál, el bot te la pregunta.\n\n## Alertas\n\n- Cuando un gasto lleva una categoría al 80% de su presupuesto (configurable) se\n  crea una notificación de aviso; al superar el límite, otra de alerta.\n- Los movimientos iguales o mayores a `LARGE_TRANSACTION_AMOUNT` también generan\n  una notificación.\n\n## Seguridad\n\n- De cada cuenta solo se guardan los últimos 4 dígitos; nunca números completos\n  ni credenciales bancarias.\n- Las contraseñas se guardan con hash y sal; nunca en texto plano.\n- Cada usuario solo puede ver y modificar sus propios datos.\n- Solo pueden registrarse mayores de 18 años.\n\n## Pruebas\n\n```bash\npytest\n```\n\n## Estructura\n\n```\napp/\n  core/       configuración, base de datos, seguridad y dependencias\n  models/     modelos SQLAlchemy\n  schemas/    esquemas Pydantic\n  routers/    endpoints\n  services/   lógica de negocio (saldos, reportes, alertas, bot)\ntests/\n```\n", "tests/test_bot.py": "from decimal import Decimal\n\nimport pytest\n\nfrom app.services.bot import detect_intent, normalize, parse_amount\n\n\n@pytest.mark.parametrize(\n    \"texto, esperado\",\n    [\n        (\"gasté 20.000 en comida\", Decimal(\"20000\")),\n        (\"pagué 20000\", Decimal(\"20000\")),\n        (\"gasté 20k\", Decimal(\"20000\")),\n        (\"pagué 80 mil de arriendo\", Decimal(\"80000\")),\n        (\"me pagaron 1.500.000\", Decimal(\"1500000\")),\n        (\"recibí 1.5 millones\", Decimal(\"1500000\")),\n        (\"recibí 2,5 millones\", Decimal(\"2500000\")),\n        (\"gasté 12500,50\", Decimal(\"12500.50\")),\n        (\"hola, ¿qué tal?\", None),\n    ],\n)\ndef test_parse_amount(texto, esperado):\n    assert parse_amount(texto) == esperado\n\n\ndef test_normalize_quita_tildes():\n    assert normalize(\"  Gasté   MÁS  \") == \"gaste mas\"\n\n\n@pytest.mark.parametrize(\n    \"texto, intencion\",\n    [\n        (\"gasté 20000 en comida\", \"expense\"),\n        (\"recibí mi salario\", \"income\"),\n        (\"me pagaron 500000\", \"income\"),\n        (\"cuánto tengo\", \"balance\"),\n        (\"cuánto gasté este mes\", \"spending\"),\n        (\"últimos movimientos\", \"recent\"),\n        (\"dame un resumen\", \"summary\"),\n        (\"buenos días\", \"help\"),\n    ],\n)\ndef test_detect_intent(texto, intencion):\n    assert detect_intent(normalize(texto)) == intencion\n\n\ndef mensaje(client, headers, texto):\n    response = client.post(\"/bot/message\", json={\"text\": texto}, headers=headers)\n    assert response.status_code == 200, response.text\n    return response.json()\n\n\ndef test_bot_requiere_autenticacion(client):\n    assert client.post(\"/bot/message\", json={\"text\": \"hola\"}).status_code == 401\n\n\ndef test_bot_registra_un_gasto(client, auth_headers, account_id, categories):\n    respuesta = mensaje(client, auth_headers, \"gasté 20.000 en almuerzo\")\n    assert respuesta[\"action\"] == \"transaction_created\"\n    assert \"$20.000\" in respuesta[\"reply\"]\n\n    historial = client.get(\"/transactions\", headers=auth_headers).json()\n    assert historial[\"total\"] == 1\n    tx = historial[\"items\"][0]\n    assert Decimal(tx[\"amount\"]) == Decimal(\"20000\")\n    assert tx[\"type\"] == \"expense\"\n    assert tx[\"category_id\"] == categories[\"Alimentación\"]\n    assert tx[\"account_id\"] == account_id\n\n\ndef test_bot_registra_un_ingreso(client, auth_headers, account_id, categories):\n    respuesta = mensaje(client, auth_headers, \"recibí 1.500.000 de salario\")\n    assert respuesta[\"action\"] == \"transaction_created\"\n    assert respuesta[\"data\"][\"category\"] == \"Salario\"\n\n    cuenta = client.get(f\"/accounts/{account_id}\", headers=auth_headers).json()\n    assert Decimal(cuenta[\"balance\"]) == Decimal(\"2500000\")\n\n\ndef test_bot_usa_otros_gastos_si_no_reconoce_la_categoria(client, auth_headers, account_id):\n    respuesta = mensaje(client, auth_headers, \"gasté 5000 en algo raro\")\n    assert respuesta[\"data\"][\"category\"] == \"Otros gastos\"\n\n\ndef test_bot_gasto_de_ayer(client, auth_headers, account_id):\n    respuesta = mensaje(client, auth_headers, \"ayer gasté 3000 en bus\")\n    assert respuesta[\"data\"][\"category\"] == \"Transporte\"\n    tx = client.get(\"/transactions\", headers=auth_headers).json()[\"items\"][0]\n    assert tx[\"date\"] == respuesta[\"data\"][\"date\"]\n\n\ndef test_bot_pide_monto_si_falta(client, auth_headers, account_id):\n    respuesta = mensaje(client, auth_headers, \"gasté en comida\")\n    assert respuesta[\"action\"] == \"needs_info\"\n    assert client.get(\"/transactions\", headers=auth_headers).json()[\"total\"] == 0\n\n\ndef test_bot_sin_cuentas(client, auth_headers):\n    respuesta = mensaje(client, auth_headers, \"gasté 5000 en bus\")\n    assert respuesta[\"action\"] == \"needs_info\"\n    assert \"cuenta\" in respuesta[\"reply\"]\n\n\ndef test_bot_pregunta_la_cuenta_si_hay_varias(client, auth_headers, account_id):\n    nequi = client.post(\n        \"/accounts\",\n        json={\"name\": \"Nequi\", \"account_type\": \"wallet\", \"initial_balance\": \"0\"},\n        headers=auth_headers,\n    ).json()\n\n    ambiguo = mensaje(client, auth_headers, \"gasté 5000 en bus\")\n    assert ambiguo[\"action\"] == \"needs_info\"\n    assert \"Nequi\" in ambiguo[\"reply\"]\n    assert client.get(\"/transactions\", headers=auth_headers).json()[\"total\"] == 0\n\n    claro = mensaje(client, auth_headers, \"gasté 5000 en bus con nequi\")\n    assert claro[\"action\"] == \"transaction_created\"\n    tx = client.get(\"/transactions\", headers=auth_headers).json()[\"items\"][0]\n    assert tx[\"account_id\"] == nequi[\"id\"]\n\n\ndef test_bot_consulta_saldo(client, auth_headers, account_id):\n    respuesta = mensaje(client, auth_headers, \"cuánto tengo\")\n    assert respuesta[\"action\"] == \"balance\"\n    assert \"$1.000.000\" in respuesta[\"reply\"]\n    assert \"Bancolombia\" in respuesta[\"reply\"]\n\n\ndef test_bot_consulta_gasto_por_categoria(client, auth_headers, account_id):\n    mensaje(client, auth_headers, \"gasté 20.000 en almuerzo\")\n    mensaje(client, auth_headers, \"gasté 30.000 en mercado\")\n    mensaje(client, auth_headers, \"pagué 10.000 de taxi\")\n\n    comida = mensaje(client, auth_headers, \"cuánto gasté en comida este mes\")\n    assert comida[\"action\"] == \"spending\"\n    assert \"$50.000\" in comida[\"reply\"]\n\n    total = mensaje(client, auth_headers, \"cuánto gasté este mes\")\n    assert \"$60.000\" in total[\"reply\"]\n\n\ndef test_bot_ultimos_movimientos_y_resumen(client, auth_headers, account_id):\n    vacio = mensaje(client, auth_headers, \"últimos movimientos\")\n    assert \"Aún no tienes movimientos\" in vacio[\"reply\"]\n\n    mensaje(client, auth_headers, \"recibí 500.000 de salario\")\n    mensaje(client, auth_headers, \"gasté 100.000 en mercado\")\n\n    recientes = mensaje(client, auth_headers, \"últimos movimientos\")\n    assert recientes[\"reply\"].count(\"\\n- \") == 2\n\n    resumen = mensaje(client, auth_headers, \"resumen\")\n    assert resumen[\"action\"] == \"summary\"\n    assert \"$500.000\" in resumen[\"reply\"]\n    assert \"Alimentación\" in resumen[\"reply\"]\n\n\ndef test_bot_ayuda_con_mensaje_desconocido(client, auth_headers):\n    respuesta = mensaje(client, auth_headers, \"buenos días\")\n    assert respuesta[\"action\"] == \"help\"\n    assert \"gasté\" in respuesta[\"reply\"]\n\n\ndef test_bot_dispara_alertas_de_presupuesto(client, auth_headers, account_id, categories):\n    client.post(\n        \"/budgets\",\n        json={\"category_id\": categories[\"Alimentación\"], \"monthly_limit\": \"50000\"},\n        headers=auth_headers,\n    )\n    mensaje(client, auth_headers, \"gasté 45.000 en comida\")\n    kinds = [n[\"kind\"] for n in client.get(\"/notifications\", headers=auth_headers).json()]\n    assert kinds == [\"budget_warning\"]\n"}}}''')


def mostrar_lista():
    print("Partes del proyecto:\n")
    for numero, parte in PARTES.items():
        print(f"  {numero}. {parte['titulo']}")
        print(f"     commit: {parte['commit']}")
    print("\nEjemplo: python ../crear_proyecto.py 2")


def escribir_parte(numero):
    parte = PARTES[str(numero)]
    print(f"\n=== Parte {numero}: {parte['titulo']} ===")
    for ruta, contenido in parte["archivos"].items():
        destino = Path(ruta)
        existia = destino.exists()
        destino.parent.mkdir(parents=True, exist_ok=True)
        with open(destino, "w", encoding="utf-8", newline="\n") as f:
            f.write(contenido)
        print(f"  {'actualizado' if existia else 'creado     '}  {ruta}")


def mostrar_commit(numero):
    commit = PARTES[str(numero)]["commit"]
    print("\nAhora haz el commit:")
    print("  git add .")
    print(f'  git commit -m "{commit}"')


def main():
    if len(sys.argv) != 2 or sys.argv[1] in ("-h", "--help", "lista"):
        mostrar_lista()
        return
    argumento = sys.argv[1]
    if argumento == "todo":
        for numero in PARTES:
            escribir_parte(int(numero))
        print("\nProyecto completo creado.")
        return
    if argumento not in PARTES:
        print(f"La parte '{argumento}' no existe. Usa: lista, todo o un número del 1 al {len(PARTES)}.")
        sys.exit(1)
    escribir_parte(int(argumento))
    mostrar_commit(int(argumento))


if __name__ == "__main__":
    main()
